    /** 无 locale 服务时的最小翻译（防止 props.t 缺失导致页面白屏）。 */
    function fallbackTranslate(key, params) {
      var template = zh[key] !== undefined ? zh[key] : key;
      if (!params) return template;
      return template.replace(/\{(\w+)\}/g, function (match, name) {
        return Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : match;
      });
    }

    function messageOf(error) {
      if (!error) return "unknown error";
      if (typeof error === "string") return error;
      if (error.message) return error.message;
      return String(error);
    }

    function modelLabel(model) {
      var id = typeof model.id === "string" ? model.id : "";
      var name = typeof model.name === "string" ? model.name : "";
      return name !== "" && name !== id ? name + " (" + id + ")" : id;
    }

    function providerLabel(group) {
      var id = typeof group.id === "string" ? group.id : "";
      var name = typeof group.name === "string" ? group.name : "";
      return name !== "" && name !== id ? name + " (" + id + ")" : id;
    }

    /**
     * 从模型目录条目里抽出可选推理档位。
     * 契约（dsh-llm LlmModelReasoningInfo）：
     *   model.reasoning = { efforts: [{ id, name }], defaultEffort? }
     * 不支持的模型**整个 reasoning 字段缺失**（不是空数组）→ 返回空数组，调用方据此禁用控件。
     * @param model - modelCatalog() 的 groups[].models[] 单项（任意形状，逐项校验）。
     * @returns [{ id, label }]；label 优先取 effort.name，缺失时退回 id。
     */
    function reasoningEffortsOf(model) {
      var reasoning = model && typeof model === "object" ? model.reasoning : undefined;
      if (!reasoning || typeof reasoning !== "object") return [];
      var list = Array.isArray(reasoning.efforts) ? reasoning.efforts : [];
      var out = [];
      for (var i = 0; i < list.length; i += 1) {
        var effort = list[i];
        if (!effort || typeof effort !== "object") continue;
        var id = typeof effort.id === "string" ? effort.id : "";
        if (id === "") continue;
        var name = typeof effort.name === "string" ? effort.name : "";
        out.push({ id: id, label: name !== "" ? name : id });
      }
      return out;
    }

    /**
     * 行的推理强度归一为字符串（缺字段 / 非字符串都当空串 = 不配置，继承父会话）。
     * 注意不能用 row.reasoningEffort !== "" 直接判断：老数据没有该键，undefined !== "" 为真。
     */
    function effortOf(row) {
      return row && typeof row.reasoningEffort === "string" ? row.reasoningEffort : "";
    }

    /* ── 纯数据层：settings value.skills ↔ 编辑行 ─────────────────── */

    function emptyRow(name) {
      return { name: name, provider: "", model: "", reasoningEffort: "", extra: {} };
    }

    function copyRow(row) {
      var extra = {};
      for (var key in row.extra) {
        if (Object.prototype.hasOwnProperty.call(row.extra, key)) extra[key] = row.extra[key];
      }
      return {
        name: row.name,
        provider: row.provider,
        model: row.model,
        reasoningEffort: effortOf(row),
        extra: extra
      };
    }

    /**
     * 把 settings 里的 skills 数组转成编辑行。
     * 除 name/provider/model/reasoningEffort 之外的字段（maxTokens 等）原样收进 extra，写回时保留。
     * @param skills - configForms 快照里的 value.skills（任意形状，逐项校验）。
     * @returns 编辑行数组（顺序与存储顺序一致）。
     */
    function rowsFromSkills(skills) {
      var rows = [];
      if (!Array.isArray(skills)) return rows;
      for (var i = 0; i < skills.length; i += 1) {
        var entry = skills[i];
        if (!entry || typeof entry.name !== "string" || entry.name === "") continue;
        var extra = {};
        for (var key in entry) {
          if (!Object.prototype.hasOwnProperty.call(entry, key)) continue;
          // reasoningEffort 已提升为一等字段，不能再进 extra，否则写回时会重复/冲突。
          if (key === "name" || key === "provider" || key === "model" || key === "reasoningEffort") continue;
          extra[key] = entry[key];
        }
        rows.push({
          name: entry.name,
          provider: typeof entry.provider === "string" ? entry.provider : "",
          model: typeof entry.model === "string" ? entry.model : "",
          reasoningEffort: typeof entry.reasoningEffort === "string" ? entry.reasoningEffort : "",
          extra: extra
        });
      }
      return rows;
    }

    /**
     * 编辑行 → 待写入的 skills 数组。
     * 规则（第 1 条是正确性关键）：
     *   1. provider 为空 → 整行不写入（= 继承父模型）；否则 delegate 会拿空 provider 建路由。
     *   2. model 为空 → 不写 model 键（供应商默认模型），绝不写空字符串（否则 UNKNOWN_MODEL）。
     *   3. reasoningEffort 为空 → 不写该键（绝不写空串），继承父会话的推理强度。
     *   4. extra（maxTokens 等）与未知 skill 名原样保留，不静默丢配置。
     * @param rows - 编辑行数组。
     * @returns 可提交给 configForms.mutate 的 skills 数组。
     */
    function rowsToSkills(rows) {
      var out = [];
      if (!Array.isArray(rows)) return out;
      for (var i = 0; i < rows.length; i += 1) {
        var row = rows[i];
        if (!row || typeof row.name !== "string" || row.name === "") continue;
        var provider = typeof row.provider === "string" ? row.provider : "";
        if (provider === "") continue;
        var item = {};
        for (var key in row.extra) {
          if (!Object.prototype.hasOwnProperty.call(row.extra, key)) continue;
          if (key === "reasoningEffort") continue; // 以一等字段为准，不让 extra 覆盖/重复
          item[key] = row.extra[key];
        }
        item.name = row.name;
        item.provider = provider;
        var model = typeof row.model === "string" ? row.model : "";
        if (model !== "") item.model = model;
        var effort = effortOf(row);
        if (effort !== "") item.reasoningEffort = effort;
        out.push(item);
      }
      return out;
    }

    /** 已知 13 个代理按固定顺序，未知 skill 名按存储顺序追加（不丢用户配置）。 */
    function displayRows(stored) {
      var known = {};
      var unknown = [];
      for (var i = 0; i < stored.length; i += 1) {
        if (SKILL_NAMES.indexOf(stored[i].name) >= 0) known[stored[i].name] = stored[i];
        else unknown.push(stored[i]);
      }
      var rows = [];
      for (var j = 0; j < SKILL_NAMES.length; j += 1) {
        var name = SKILL_NAMES[j];
        rows.push(known[name] !== undefined ? known[name] : emptyRow(name));
      }
      for (var k = 0; k < unknown.length; k += 1) rows.push(unknown[k]);
      return rows;
    }

    /* ── 纯数据层：Config.customRoles ↔ 编辑行 ────────────────────── */

    /**
     * 角色类型（队长 / 队员）的合法值；其余（缺省 / 脏值）返回 ""。
     * 与 src/roles.ts 的 RoleKind 逐字一致，"": 「还没选」= 必填校验会拦下的状态。
     */
    function roleKindValue(value) {
      return value === "lead" || value === "member" ? value : "";
    }

    function emptyRole() {
      // kind = "": 新建空白角色默认不选类型，由用户在表单里显式选（必填）。
      return { name: "", description: "", prompt: "", tier: "ro", kind: "", tools: [] };
    }

    function copyRole(role) {
      var tools = [];
      var list = role && Array.isArray(role.tools) ? role.tools : [];
      for (var i = 0; i < list.length; i += 1) {
        if (typeof list[i] === "string" && list[i] !== "" && tools.indexOf(list[i]) < 0) tools.push(list[i]);
      }
      return {
        name: typeof role.name === "string" ? role.name : "",
        description: typeof role.description === "string" ? role.description : "",
        prompt: typeof role.prompt === "string" ? role.prompt : "",
        tier: ROLE_TIERS.indexOf(role.tier) >= 0 ? role.tier : "ro",
        kind: roleKindValue(role.kind),
        tools: tools
      };
    }

    /**
     * Config.customRoles → 编辑行。
     * 老配置没有该字段（undefined）时返回空数组，页面按「还没有自定义角色」展示。
     * @param roles - configForms 快照里的 value.customRoles（任意形状，逐项校验）。
     * @returns 编辑行数组。
     */
    function rowsFromCustomRoles(roles) {
      var rows = [];
      if (!Array.isArray(roles)) return rows;
      for (var i = 0; i < roles.length; i += 1) {
        var entry = roles[i];
        if (!entry || typeof entry !== "object") continue;
        var row = copyRole(entry);
        // 老配置没有 kind：运行时按 member 解析（src/roles.ts 的 resolveRoleKind 兜底），
        // 这里同口径补上，免得一次「保存」把用户的存量角色卡在「必填」校验上。
        if (row.kind === "") row.kind = "member";
        rows.push(row);
      }
      return rows;
    }

    /** 编辑行 → 待写入的 customRoles 数组（只写受控字段：name/description/prompt/tier/tools）。 */
    function rolesToCustomRoles(rows) {
      var out = [];
      if (!Array.isArray(rows)) return out;
      for (var i = 0; i < rows.length; i += 1) {
        var role = rows[i];
        if (!role || typeof role !== "object") continue;
        out.push(copyRole(role));
      }
      return out;
    }

    /* ── 纯数据层：Config.roleOverrides（内置角色的字段级覆盖） ─────── */

    /**
     * 允许被 override 覆盖的档位：五个可委派档位 + 内置主代理档位 "main"
     * （co-orchestrator 在目录里就是 main，覆盖它不能把档位改成未知值）。
     */
    var OVERRIDE_TIERS = ROLE_TIERS.concat(["main"]);

    /** 内置角色在 ROLE_CATALOG 里的条目（缺省 / 形状不对返回 null）。 */
    function builtinRoleOf(name) {
      var key = typeof name === "string" ? name : "";
      var roles = ROLE_CATALOG && ROLE_CATALOG.roles ? ROLE_CATALOG.roles : {};
      if (key === "" || !Object.prototype.hasOwnProperty.call(roles, key)) return null;
      var entry = roles[key];
      return entry && typeof entry === "object" ? entry : null;
    }

    /** 档位 → 工具 id 列表（与「角色库」里 customRoles[].tools 同一口径）。 */
    function toolIdsOfTier(tier) {
      var list = tierToolsOf(tier);
      var out = [];
      for (var i = 0; i < list.length; i += 1) {
        var id = toolIdOfPlugin(list[i].plugin);
        if (id !== "" && out.indexOf(id) < 0) out.push(id);
      }
      return out;
    }

    /** 工具 id 列表 → 详情面板用的只读工具项（与 tierToolsOf 同形状）。 */
    function toolsFromIds(ids) {
      var out = [];
      var list = Array.isArray(ids) ? ids : [];
      for (var i = 0; i < list.length; i += 1) {
        var item = toolItemOf(list[i]);
        if (item === null) continue;
        out.push({
          plugin: item.plugin,
          pluginShort: pluginShortName(item.plugin),
          label: "",
          note: ""
        });
      }
      return out;
    }

    /** 工具 id 列表去重成字符串数组（顺序保留）。 */
    function normalizeToolIds(list) {
      var out = [];
      var source = Array.isArray(list) ? list : [];
      for (var i = 0; i < source.length; i += 1) {
        if (typeof source[i] !== "string" || source[i] === "") continue;
        if (out.indexOf(source[i]) < 0) out.push(source[i]);
      }
      return out;
    }

    /** 两组工具 id 是否等价（顺序无关）。 */
    function sameToolIds(left, right) {
      var a = normalizeToolIds(left).slice().sort();
      var b = normalizeToolIds(right).slice().sort();
      if (a.length !== b.length) return false;
      for (var i = 0; i < a.length; i += 1) if (a[i] !== b[i]) return false;
      return true;
    }

    /** 单条 override 归一：只保留 name / description / prompt / tier / tools。 */
    function copyOverride(item) {
      var out = { name: "" };
      if (!item || typeof item !== "object") return out;
      out.name = typeof item.name === "string" ? item.name.trim() : "";
      if (typeof item.description === "string") out.description = item.description;
      if (typeof item.prompt === "string") out.prompt = item.prompt;
      if (typeof item.tier === "string" && OVERRIDE_TIERS.indexOf(item.tier) >= 0) out.tier = item.tier;
      var tools = normalizeToolIds(item.tools);
      if (tools.length > 0) out.tools = tools;
      return out;
    }

    /** Config.roleOverrides → 归一数组（空名 / 非对象条目跳过，同名校后者覆盖前者）。 */
    function rowsFromOverrides(list) {
      var out = [];
      if (!Array.isArray(list)) return out;
      for (var i = 0; i < list.length; i += 1) {
        var row = copyOverride(list[i]);
        if (row.name === "") continue;
        var replaced = false;
        for (var j = 0; j < out.length; j += 1) {
          if (out[j].name !== row.name) continue;
          out[j] = row;
          replaced = true;
          break;
        }
        if (!replaced) out.push(row);
      }
      return out;
    }

    /** 按角色名取 override（找不到返回 null）。 */
    function findOverride(list, name) {
      var key = typeof name === "string" ? name.trim() : "";
      if (key === "") return null;
      var rows = Array.isArray(list) ? list : [];
      for (var i = 0; i < rows.length; i += 1) {
        if (rows[i] && rows[i].name === key) return rows[i];
      }
      return null;
    }

    /**
     * 内置默认 + 编辑草稿 → **只含差异字段**的 override。
     * 规则（与 src/roles.ts 的合并语义对齐）：
     *   - description / prompt：与内置默认（含首尾空白）不同才写；prompt 留空 = 恢复默认，不写；
     *   - tier：必须是合法档位且与内置不同才写；
     *   - tools：留空 = 沿用档位推导，不写；否则与「内置档位推导出的工具集」不同才写。
     * 没有任何差异 → 返回 null（调用方据此从数组里删掉该条）。
     * @param name - 内置角色名
     * @param draft - { description, prompt, tier, tools }
     */
    function diffOverrideOf(name, draft) {
      var base = builtinRoleOf(name);
      if (base === null || !draft || typeof draft !== "object") return null;
      var source = draft;
      var out = { name: typeof name === "string" ? name.trim() : "" };
      var changed = false;
      var baseDescription = typeof base.description === "string" ? base.description : "";
      var draftDescription = typeof source.description === "string" ? source.description : "";
      if (draftDescription.trim() !== baseDescription.trim()) {
        out.description = draftDescription;
        changed = true;
      }
      var basePrompt = typeof base.brief === "string" ? base.brief : "";
      var draftPrompt = typeof source.prompt === "string" ? source.prompt : "";
      if (draftPrompt.trim() !== "" && draftPrompt.trim() !== basePrompt.trim()) {
        out.prompt = draftPrompt;
        changed = true;
      }
      var baseTier = typeof base.tier === "string" ? base.tier : "";
      var draftTier = typeof source.tier === "string" && OVERRIDE_TIERS.indexOf(source.tier) >= 0 ? source.tier : "";
      if (draftTier !== "" && draftTier !== baseTier) {
        out.tier = draftTier;
        changed = true;
      }
      var draftTools = normalizeToolIds(source.tools);
      if (draftTools.length > 0 && !sameToolIds(draftTools, toolIdsOfTier(baseTier))) {
        out.tools = draftTools;
        changed = true;
      }
      return changed ? out : null;
    }

    /**
     * 把一条编辑草稿写回 override 表：差异为空 → 删除该条；否则替换 / 追加。
     * @param overrides - 现有 override 数组（任意形状，逐项归一）
     * @param draft - { name, description, prompt, tier, tools }
     * @returns 待写入 Config.roleOverrides 的新数组
     */
    function applyOverrideDraft(overrides, draft) {
      var list = rowsFromOverrides(overrides);
      var name = draft && typeof draft.name === "string" ? draft.name.trim() : "";
      var patch = name !== "" ? diffOverrideOf(name, draft) : null;
      var out = [];
      var placed = false;
      for (var i = 0; i < list.length; i += 1) {
        if (list[i].name !== name) {
          out.push(list[i]);
          continue;
        }
        // 同名的重复条目一并丢弃（手改坏的配置在这里自愈）。
        if (patch !== null && !placed) {
          out.push(patch);
          placed = true;
        }
      }
      if (patch !== null && !placed) out.push(patch);
      return out;
    }

    /* ── 纯数据层：绑定工具分组 / 角色模板（模板新建用） ───────────── */

    /**
     * 工具分组：id 就是写进 Config.customRoles[].tools 的插件 id
     * （与 schema index.ts:152 的 `z.array(z.string().min(1))` 同口径，不做形状校验）。
     * gate 只是展示用的门控说明（bash 仅 POSIX / pwsh 仅 Windows / mcp 需授权）。
     */
    var TOOL_GROUPS = [
      {
        id: "file",
        labelKey: "toolGroupFile",
        items: [
          { id: "tool-fs", plugin: "dsh-tool-fs" },
          { id: "tool-fs-search", plugin: "dsh-tool-fs-search" }
        ]
      },
      {
        id: "net",
        labelKey: "toolGroupNet",
        items: [{ id: "tool-web", plugin: "dsh-tool-web" }]
      },
      {
        id: "exec",
        labelKey: "toolGroupExec",
        items: [
          { id: "tool-bash", plugin: "dsh-tool-bash", gate: "posix" },
          { id: "tool-pwsh", plugin: "dsh-tool-pwsh", gate: "windows" }
        ]
      },
      {
        id: "orch",
        labelKey: "toolGroupOrch",
        items: [
          { id: "tool-skill", plugin: "dsh-tool-skill" },
          { id: "tool-todo", plugin: "dsh-tool-todo" },
          { id: "tool-jobs", plugin: "dsh-tool-jobs" },
          { id: "tool-goal", plugin: "dsh-tool-goal" },
          { id: "tool-ask-user", plugin: "dsh-tool-ask-user" },
          { id: "tool-delegation", plugin: "dsh-tool-delegation" }
        ]
      },
      {
        id: "ext",
        labelKey: "toolGroupExt",
        items: [{ id: "mcp-github", plugin: "mcp-github", gate: "mcp" }]
      }
    ];

    /** 单个工具项在 TOOL_GROUPS 里的登记（找不到返回 null）。 */
    function toolItemOf(id) {
      for (var g = 0; g < TOOL_GROUPS.length; g += 1) {
        var items = TOOL_GROUPS[g].items;
        for (var i = 0; i < items.length; i += 1) if (items[i].id === id) return items[i];
      }
      return null;
    }

    /**
     * 角色目录里的插件短名 → 本页工具 id。
     * pluginShortName 已经剥掉 dsh-tool- 前缀（dsh-tool-fs → fs），所以这里补回 tool-；
     * dsh-tool-web-search / dsh-tool-web-fetch 都归到 tool-web；mcp-github 原样保留。
     */
    function toolIdOfPlugin(plugin) {
      var short = pluginShortName(plugin);
      if (short.indexOf("mcp-") === 0) return short;
      if (short.indexOf("web") === 0) return "tool-web";
      return "tool-" + short;
    }

    /** 档位对应的工具 id 列表（点档位快捷按钮时批量勾选它）。 */
    function tierToolIds(tier) {
      var list = tierToolsOf(tier);
      var out = [];
      for (var i = 0; i < list.length; i += 1) {
        var id = toolIdOfPlugin(list[i] && list[i].plugin ? list[i].plugin : "");
        if (id !== "" && out.indexOf(id) < 0) out.push(id);
      }
      return out;
    }

    /** 勾了 Shell 却没勾文件工具 → 回调里没法定位文件，给一条黄色提示。 */
    function shellWithoutFs(tools) {
      var list = Array.isArray(tools) ? tools : [];
      var hasShell = list.indexOf("tool-bash") >= 0 || list.indexOf("tool-pwsh") >= 0;
      return hasShell && list.indexOf("tool-fs") < 0;
    }

    /**
     * 模板清单：18 个内置角色 → 空白角色（co-team-lead / co-team-member 亦在内）。
     * 数据全部来自构建期生成的 ROLE_CATALOG，运行期零 IO。
     * 注意：co-orchestrator 的提示词写死了成员名单，**不再作为模板**（它仍是会话主代理）。
     */
    function roleTemplateList() {
      var roles = ROLE_CATALOG && ROLE_CATALOG.roles ? ROLE_CATALOG.roles : {};
      var out = [];
      for (var i = 0; i < BUILTIN_ROLE_NAMES.length; i += 1) {
        var name = BUILTIN_ROLE_NAMES[i];
        var entry = roles[name] && typeof roles[name] === "object" ? roles[name] : null;
        var tier = entry && typeof entry.tier === "string" ? entry.tier : "";
        var tools = tierToolIds(tier);
        out.push({
          id: name,
          name: name,
          main: false,
          description: entry && typeof entry.description === "string" ? entry.description : "",
          brief: entry && typeof entry.brief === "string" ? entry.brief : "",
          tier: tier,
          // 模板自带类型：新建角色按模板预填「角色类型」（co-orchestrator / co-team-lead → lead，
          // 其余 → member）。目录缺 kind 时由 roleKindOf 的兜底名单补上。
          kind: roleKindOf(name),
          tools: tools
        });
      }
      out.push({
        id: "blank", name: "", blank: true, main: false,
        description: "", brief: "", tier: "", kind: "", tools: []
      });
      return out;
    }

    /** 按 id 取模板（空白角色用 id=""）。 */
    function templateOf(id) {
      var list = roleTemplateList();
      for (var i = 0; i < list.length; i += 1) if (list[i].id === id) return list[i];
      return null;
    }

    /** 模板新建的默认名：加 -copy 后缀防与内置角色重名，重复时再追加序号。 */
    function templateRoleName(base, taken) {
      var raw = typeof base === "string" && base !== "" ? base : "co-role";
      var used = Array.isArray(taken) ? taken : [];
      var candidate = raw + "-copy";
      var n = 2;
      while (used.indexOf(candidate) >= 0) {
        candidate = raw + "-copy-" + n;
        n += 1;
      }
      return candidate;
    }

    /**
     * 角色库搜索匹配（纯函数）：关键词与「角色名 + 职责」文本的**不区分大小写**子串匹配。
     * 只影响渲染过滤，不改任何数据；关键词为空（含纯空格）时全部命中。
     */
    function roleMatchesSearch(keyword, text) {
      var needle = typeof keyword === "string" ? keyword.trim().toLowerCase() : "";
      if (needle === "") return true;
      var haystack = typeof text === "string" ? text.toLowerCase() : "";
      return haystack.indexOf(needle) >= 0;
    }

    /**
     * 提交前的前端校验：违反任一条就不写配置（写进去会污染技能表或让子代理拿错档位）。
     * 规则：name 必填 + kebab-case + 不撞内置 SKILL_NAMES + 表内不重名；description / prompt 非空。
     * @returns 与 rows 等长的错误数组，空串表示该字段合法。
     */
    function validateRoles(rows) {
      var errors = [];
      var counts = {};
      var list = Array.isArray(rows) ? rows : [];
      var i;
      for (i = 0; i < list.length; i += 1) {
        var name = list[i] && typeof list[i].name === "string" ? list[i].name : "";
        if (name === "") continue;
        counts[name] = (counts[name] || 0) + 1;
      }
      for (i = 0; i < list.length; i += 1) {
        var role = list[i] || {};
        var raw = typeof role.name === "string" ? role.name : "";
        var error = { name: "", description: "", prompt: "", kind: "" };
        if (raw === "") error.name = "nameRequired";
        else if (!ROLE_NAME_PATTERN.test(raw)) error.name = "nameFormat";
        else if (SKILL_NAMES.indexOf(raw) >= 0) error.name = "nameBuiltin";
        else if (counts[raw] > 1) error.name = "nameDuplicate";
        if (typeof role.description !== "string" || role.description.trim() === "") error.description = "required";
        if (typeof role.prompt !== "string" || role.prompt.trim() === "") error.prompt = "required";
        // 角色类型必填：漏选时保存直接被拦（空白角色尤其容易漏，它默认不选）。
        if (roleKindValue(role.kind) === "") error.kind = "kindRequired";
        errors.push(error);
      }
      return errors;
    }

    /** 错误表里被标红的字段数（0 = 可以提交）。 */
    function countRoleErrors(errors) {
      var count = 0;
      for (var i = 0; i < errors.length; i += 1) {
        var error = errors[i] || {};
        if (error.name !== "") count += 1;
        if (error.description !== "") count += 1;
        if (error.prompt !== "") count += 1;
        if (error.kind !== "") count += 1;
      }
      return count;
    }

    /* ── 纯数据层：Config.teams ↔ 编辑行 ─────────────────────────── */

    /** 团队 id 的合法形状，与服务端 Team.id 的 pattern 一致。 */
    var TEAM_ID_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

    /** 团队预设 id 的固定前缀：注册器把团队落成一个叫 `cohub-team-<slug>` 的 Agent 预设。 */
    var TEAM_PRESET_PREFIX = "cohub-team-";

    /**
     * 团队 → Agent 预设 id：与 src/team-presets.ts 的 teamPresetId **同一条规则**：
     * 显式 presetId 优先，否则按 `cohub-team-<团队 id>` 推导（服务端注册时用的就是它）。
     * 空串 / 纯空白视为「未配置」。
     */
    function teamPresetId(team) {
      var declared = team && typeof team.presetId === "string" ? team.presetId.trim() : "";
      if (declared !== "") return declared;
      return TEAM_PRESET_PREFIX + (team && typeof team.id === "string" ? team.id.trim() : "");
    }

    /**
     * 编辑面板里那个 **可改的** slug 输入框的值：
     *   1. 用户手改过（slugEdited）→ 原样返回他填的（允许暂时不合法，交给 validateTeams 标红）；
     *   2. 否则显式 presetId 剥掉 `cohub-team-` 前缀（配置里手写过 prefix 形式时）；
     *   3. 再退到团队 id —— 中文名折成空串时 id 已被 uniqueTeamId 兜底成 "team"，所以这里是 "team"。
     * 这就是根修点：中文团队名默认 slug 只能是 "team"，现在用户可以亲手填成 writing。
     */
    function teamSlugOf(team) {
      if (team && team.slugEdited === true) return typeof team.slug === "string" ? team.slug : "";
      var declared = team && typeof team.presetId === "string" ? team.presetId.trim() : "";
      if (declared.indexOf(TEAM_PRESET_PREFIX) === 0 && declared.length > TEAM_PRESET_PREFIX.length) {
        return declared.slice(TEAM_PRESET_PREFIX.length);
      }
      var id = team && typeof team.id === "string" ? team.id.trim() : "";
      return id !== "" ? id : "team";
    }

    /**
     * 卡片徽标与输入框右侧提示共用的「最终预设 id」：
     * 手改过 → `cohub-team-<手填值>`；否则沿用 teamPresetId（显式 presetId，或 cohub-team-<id>）。
     * 落库规则见 teamsToConfig —— 三处口径必须一致，否则「提示的 id」和「注册出来的 id」会漂。
     */
    function teamPresetIdOf(team) {
      if (team && team.slugEdited === true) return TEAM_PRESET_PREFIX + teamSlugOf(team);
      return teamPresetId(team);
    }

    /**
     * 团队 id 生成：name 转 kebab-case（小写、非字母数字折成单连字符、去首尾连字符）。
     * 中文名折完是空串（ASCII 折叠规则，不做音译）→ 返回 ""，由 uniqueTeamId 兜底成 "team"。
     */
    function kebabIdOf(name) {
      var raw = typeof name === "string" ? name.trim().toLowerCase() : "";
      if (raw === "") return "";
      return raw.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
    }

    /**
     * 生成不与 taken 冲突的团队 id：基准可用直接用，否则依次加 -2 / -3 …
     * （最多到 -99；极端情况退回时间戳后缀——宁可 id 难看，也不让两个团队撞 id，
     *  否则 Config.activeTeam 的含义就有歧义）。
     * @param name - 团队显示名（可中文；折叠为空时基准取 "team"）。
     * @param taken - 已被占用的 id 列表（其他团队）。
     */
    function uniqueTeamId(name, taken) {
      var base = kebabIdOf(name);
      if (base === "") base = "team";
      var used = {};
      var list = Array.isArray(taken) ? taken : [];
      for (var i = 0; i < list.length; i += 1) {
        if (typeof list[i] === "string") used[list[i]] = true;
      }
      if (used[base] !== true) return base;
      for (var n = 2; n <= 99; n += 1) {
        var candidate = base + "-" + n;
        if (used[candidate] !== true) return candidate;
      }
      return base + "-" + String(Date.now());
    }

    /**
     * 团队的有效队长（默认值规则唯一入口，下拉框默认选中与保存写回都用它）：
     *   1. 显式 lead 且（∈ members **或就是 co-orchestrator**）→ 用它；
     *   2. lead 为空（或悬空）且成员含 co-orchestrator → 选 co-orchestrator（主代理天然是调度者）；
     *   3. 否则取第一个成员；没有成员 → ""。
     *
     * ① 的 co-orchestrator 例外：主代理是团队队长而**不是子代理成员**，内置团队的 members
     * 只列专职子代理（见 src/builtin-teams.ts，dev 的 lead = co-orchestrator）。不放宽就会把
     * 「开发团队」的队长静默回退成 members[0]（co-fixer），与服务端 team-presets.ts 的
     * resolveTeamLead 口径漂移。用户自建团队的保存校验仍要求 lead ∈ members（validateTeams），
     * 这里只影响展示与写回默认值。
     */
    function effectiveTeamLead(team, customRows) {
      var members = team && Array.isArray(team.members) ? team.members : [];
      var lead = team && typeof team.lead === "string" ? team.lead : "";
      // 显式 lead 除了「是成员 / 是主代理」之外还要求**类型是队长**：队员类型当队长时
      // 服务端 resolveTeamLead 会静默回退（人格与配置不一致），客户端按「没指定」处理。
      if (lead !== "" && (members.indexOf(lead) >= 0 || lead === MAIN_AGENT_NAME)
        && roleKindOf(lead, customRows) === "lead") {
        return lead;
      }
      if (members.indexOf(MAIN_AGENT_NAME) >= 0) return MAIN_AGENT_NAME;
      for (var i = 0; i < members.length; i += 1) {
        if (roleKindOf(members[i], customRows) === "lead") return members[i];
      }
      return members.length > 0 && typeof members[0] === "string" ? members[0] : "";
    }

    /**
     * members 里**类型为队长**的角色（顺序即 members 顺序）。
     *
     * 唯一判据是 {@link roleKindOf}（与 src/roles.ts 的 resolveRoleKind 逐条对齐）：
     * 空名 / 非字符串 / 不在角色库的名字一律按 member 处理，故不会凭空多出队长。
     *
     * @param team - 团队编辑行（只用 members）
     * @param customRows - 角色库当前编辑行（自定义角色的 kind）
     * @returns 队长类型角色名数组（每次新建）
     */
    function leadKindMembersOf(team, customRows) {
      var out = [];
      var members = team && Array.isArray(team.members) ? team.members : [];
      for (var i = 0; i < members.length; i += 1) {
        var name = typeof members[i] === "string" ? members[i].trim() : "";
        if (name === "" || out.indexOf(name) >= 0) continue;
        if (roleKindOf(name, customRows) === "lead") out.push(name);
      }
      return out;
    }

    /**
     * 勾选 / 取消一个成员的**纯函数判定**（controller 与自测共用；不改入参）。
     *
     * 规则（一个团队最多一个队长类型角色）：
     *   ① 取消勾选 → 从 members 移除；取消的正是当前 lead → lead 清空（团队暂时无队长，
     *      保存时由 validateTeams 报「必须有一位队长类型角色」）；
     *   ② 勾选的是队长类型角色：
     *      - members 里还没有队长类型 → 允许，并**自动设为队长**；
     *      - members 里已有队长类型 → **拒绝**（members / lead 原样返回，rejected = 该角色名，
     *        currentLead = 现队长名，供 UI 提示）；
     *   ③ 勾选的是队员类型 → 照常加入，lead 不动。
     *
     * @param team - 团队编辑行（members / lead）
     * @param roleName - 被勾选 / 取消的角色名
     * @param customRows - 角色库当前编辑行（决定 kind）
     * @returns `{ members, lead, rejected, currentLead }`；rejected 非空 = 本次勾选被拒绝
     */
    function toggleMemberState(team, roleName, customRows) {
      var name = typeof roleName === "string" ? roleName.trim() : "";
      var members = team && Array.isArray(team.members) ? team.members.slice() : [];
      var lead = team && typeof team.lead === "string" ? team.lead : "";
      if (name === "") return { members: members, lead: lead, rejected: "", currentLead: "" };
      var at = members.indexOf(name);
      if (at >= 0) {
        members.splice(at, 1);
        return {
          members: members,
          lead: lead === name ? "" : lead,
          rejected: "",
          currentLead: ""
        };
      }
      var kind = roleKindOf(name, customRows);
      var leadsNow = leadKindMembersOf({ members: members }, customRows);
      if (kind === "lead" && leadsNow.length > 0) {
        return { members: members, lead: lead, rejected: name, currentLead: leadsNow[0] };
      }
      members.push(name);
      return {
        members: members,
        lead: kind === "lead" ? name : lead,
        rejected: "",
        currentLead: ""
      };
    }

    /** 成员职责缺失时的兜底文案（与 src/team-presets.ts 的 EMPTY_DUTY 逐字一致）。 */
    var EMPTY_DUTY = "（未填写职责）";

    /** 队长职责缺失时的兜底正文（与 src/team-presets.ts 的 body 兜底逐字一致）。 */
    var EMPTY_PERSONA = "你的职责：分析需求 → 委派给本团队的专职子代理 → 审核并汇总结果；绝不亲自操作文件（除非你本身是执行型角色）。";

    /**
     * 团队主代理 persona 的**本地重建**（团队编辑页的实时预览用），与
     * src/team-presets.ts 的 {@link buildTeamPersona} 同构：
     *
     *   ① 身份行：`你是 cohub 团队「<团队名>」的主代理（团队 id <id>；队长 <lead>）。`
     *   ② 队长职责全文（内置取 brief、自定义取 prompt；空则用运行时同一条兜底正文）
     *   ③ `团队成员（共 N 人）：` + 每行 `- <成员名>：<该角色 description>`，队长自己标「（你）」
     *
     * 三段用 `join("\n\n")` 拼（段间空一行），查不到的成员跳过并在计数里不出现——与运行时的
     * `persona skip unknown member` 同一口径，所以预览的 N 恒等于实际注册的 N。
     *
     * @param team - 团队编辑行（members / name / lead / id）
     * @param customRows - 角色库当前编辑行（自定义角色的 kind / prompt / description）
     * @param overrideRows - Config.roleOverrides（内置角色覆盖后，预览必须显示覆盖后的职责）
     * @returns { text, count }（count = 参与 persona 的成员数，即「共 N 人」）
     */
    function leadPersonaPreview(team, customRows, overrideRows) {
      var members = team && Array.isArray(team.members) ? team.members : [];
      var teamName = team && typeof team.name === "string" ? team.name.trim() : "";
      var teamId = teamSlugOf(team);
      var lead = effectiveTeamLead(team, customRows);
      var leadDetail = roleDetailOf(lead, customRows, overrideRows);
      var brief = typeof leadDetail.prompt === "string" ? leadDetail.prompt.trim() : "";
      var head = "你是 cohub 团队「" + teamName + "」的主代理（团队 id " + teamId +
        "；队长 " + (lead !== "" ? lead : "（未指定）") + "）。";
      var lines = [];
      for (var i = 0; i < members.length; i += 1) {
        var member = members[i];
        var detail = roleDetailOf(member, customRows, overrideRows);
        if (detail.promptSource === "none") continue;
        var duty = typeof detail.description === "string" ? detail.description.trim() : "";
        lines.push("- " + member + "：" + (duty !== "" ? duty : EMPTY_DUTY) + (member === lead ? "（你）" : ""));
      }
      var roster = lines.length > 0
        ? ["团队成员（共 " + lines.length + " 人）："].concat(lines).join("\n")
        : "团队成员（共 " + lines.length + " 人）：\n- （本团队没有可列出的成员）";
      return {
        text: [head, brief !== "" ? brief : EMPTY_PERSONA, roster].join("\n\n"),
        count: lines.length
      };
    }

    /**
     * 新建团队的草稿行（id 先占位，isNew 让改名时重算 id；保存时不外泄这些草稿标记）。
     * slug 初值 = 占位 id（中文名折空后 id 就是 "team"）；slugEdited=false 表示「还没手改，跟随推导」。
     */
    function emptyTeam(id) {
      return {
        id: id, name: "", description: "", members: [], lead: "", presetId: "",
        slug: typeof id === "string" ? id : "", slugEdited: false, isNew: true
      };
    }

    /** Config.teams 的一项 → 编辑行；members 只保留非空字符串。 */
    function copyTeam(team) {
      var members = [];
      var list = team && Array.isArray(team.members) ? team.members : [];
      for (var i = 0; i < list.length; i += 1) {
        if (typeof list[i] === "string" && list[i] !== "") members.push(list[i]);
      }
      return {
        id: team && typeof team.id === "string" ? team.id : "",
        name: team && typeof team.name === "string" ? team.name : "",
        description: team && typeof team.description === "string" ? team.description : "",
        members: members,
        // 显式 presetId 原样保留：它覆盖「cohub-team-<id>」的默认推导，不能让一次保存把它丢掉。
        presetId: team && typeof team.presetId === "string" ? team.presetId : "",
        // slug 输入框的值：手改过就原样带着（改名不再覆盖），没改过则跟着 id 重新推导。
        slug: team && team.slugEdited === true
          ? (typeof team.slug === "string" ? team.slug : "")
          : teamSlugOf(team),
        slugEdited: team && team.slugEdited === true,
        // lead 悬空（指向已取消勾选的角色）也原样保留：保存时由 validateTeams 拦下并标红。
        lead: team && typeof team.lead === "string" ? team.lead : "",
        isNew: false
      };
    }

    /**
     * Config.teams → 编辑行。老配置没有该字段（undefined）时返回空数组，页面按「还没有团队」展示。
     * @param teams - configForms 快照里的 value.teams（任意形状，逐项校验）。
     */
    function rowsFromTeams(teams) {
      var rows = [];
      if (!Array.isArray(teams)) return rows;
      for (var i = 0; i < teams.length; i += 1) {
        var entry = teams[i];
        if (!entry || typeof entry !== "object") continue;
        rows.push(copyTeam(entry));
      }
      return rows;
    }

    /**
     * 内置团队（构建期由 scripts/generate-role-catalog.ts 从 src/builtin-teams.ts 写进
     * ROLE_CATALOG.builtinTeams）。它们**不是用户配置**：不进 Config.teams，页面只读展示 +
     * 提供「复制为我的团队」。缺字段 / 形状不对的条目直接跳过，绝不抛错。
     */
    function builtinTeamsOf(catalog) {
      var source = catalog && Array.isArray(catalog.builtinTeams) ? catalog.builtinTeams : [];
      var out = [];
      for (var i = 0; i < source.length; i += 1) {
        var team = source[i];
        if (!team || typeof team !== "object") continue;
        if (typeof team.id !== "string" || team.id.trim() === "") continue;
        var members = [];
        var list = Array.isArray(team.members) ? team.members : [];
        for (var m = 0; m < list.length; m += 1) {
          if (typeof list[m] === "string" && list[m] !== "") members.push(list[m]);
        }
        out.push({
          id: team.id.trim(),
          name: typeof team.name === "string" && team.name.trim() !== "" ? team.name : team.id.trim(),
          description: typeof team.description === "string" ? team.description : "",
          members: members,
          lead: typeof team.lead === "string" ? team.lead : "",
          // 显式 presetId 必须保留：内置 dev 团队覆盖成 co-orchestrator（见 builtin-teams.ts），
          // 丢了这个字段 UI 就会把展示 id 推导成 `cohub-team-dev`，与注册日志对不上。
          presetId: typeof team.presetId === "string" ? team.presetId : "",
          builtin: true
        });
      }
      return out;
    }

    /** 编辑行 → 待写入的 teams 数组（只写受控字段，草稿标记不外泄）。 */
    function teamsToConfig(rows, customRows) {
      var out = [];
      if (!Array.isArray(rows)) return out;
      for (var i = 0; i < rows.length; i += 1) {
        var team = rows[i];
        if (!team || typeof team !== "object") continue;
        var members = Array.isArray(team.members) ? team.members.slice() : [];
        var item = {
          id: typeof team.id === "string" ? team.id : "",
          name: typeof team.name === "string" ? team.name : "",
          description: typeof team.description === "string" ? team.description : "",
          members: members,
          // lead 与 members 同一次 mutate 写入：空 lead 落成默认队长，配置文件里不留空。
          lead: effectiveTeamLead({ members: members, lead: team.lead }, customRows)
        };
        // 预设 id 落库规则（不新增 schema 字段，全走已有的 presetId）：
        //   - 用户手改过 slug → 写显式 presetId = `cohub-team-<手填值>`；
        //   - 没改过 → 沿用原显式 presetId（若有），否则省略，让注册器按 cohub-team-<id> 推导。
        var presetId = typeof team.presetId === "string" ? team.presetId.trim() : "";
        if (team.slugEdited === true) {
          var slug = typeof team.slug === "string" ? team.slug.trim() : "";
          presetId = slug !== "" ? TEAM_PRESET_PREFIX + slug : "";
        }
        if (presetId !== "") item.presetId = presetId;
        out.push(item);
      }
      return out;
    }

    /**
     * 团队校验（对齐服务端 Team schema，另加页面才判得了的 id 重复）：
     *   - name 去空白后非空；
     *   - members 至少 1 个；
     *   - 预设 id 的 slug 合法（kebab-case）且表内不重复（按最终 slug 判，手改过的也算）。
     * @returns 与 rows 等长的错误数组，空串表示该字段合法。
     */
    function validateTeams(rows, customRows) {
      var list = Array.isArray(rows) ? rows : [];
      var counts = {};
      var errors = [];
      var i;
      // 重名按 **最终 slug**（预设 id 的终段）统计：手填的 slug 撞上别人的 id 同样要拦。
      for (i = 0; i < list.length; i += 1) {
        var seeded = teamSlugOf(list[i]).trim();
        if (seeded === "") continue;
        counts[seeded] = (counts[seeded] || 0) + 1;
      }
      for (i = 0; i < list.length; i += 1) {
        var team = list[i] || {};
        var error = { name: "", members: "", id: "", lead: "" };
        var teamName = typeof team.name === "string" ? team.name.trim() : "";
        // 面板上标红的是 slug 输入框（沿用 error.id 这个键，渲染层与文案不用改）。
        var slug = teamSlugOf(team).trim();
        if (teamName === "") error.name = "nameRequired";
        if (!Array.isArray(team.members) || team.members.length === 0) error.members = "required";
        if (slug === "" || !TEAM_ID_PATTERN.test(slug)) error.id = "idFormat";
        else if (counts[slug] > 1) error.id = "idDuplicate";
        // 队长必须是本团队已勾选的成员；空 lead 合法（保存时按默认规则补成有效值）。
        var lead = typeof team.lead === "string" ? team.lead : "";
        // 空 lead 保存时会落成 effectiveTeamLead（默认队长），所以校验的必须是**将要写入的那个值**，
        // 否则会出现「校验通过但写进去的队长是队员类型」的静默错配。
        var written = lead !== "" ? lead : effectiveTeamLead(team, customRows);
        // 队长类型角色每队最多一个：先按 members 统计（同名重复只算一次），再逐条判定。
        var leadMembers = leadKindMembersOf(team, customRows);
        var memberCount = Array.isArray(team.members) ? team.members.length : 0;
        if (written !== "" && (!Array.isArray(team.members) || team.members.indexOf(written) < 0)) {
          error.lead = "notMember";
        } else if (memberCount > 0 && leadMembers.length === 0) {
          // members 非空却没有队长类型成员：此时 effectiveTeamLead 会回退成 members[0]（队员类型），
          // 落到下面只会报「不是队长类型」；真正的原因是「缺一个队长类型角色」，故优先报这条。
          error.lead = "leadRequired";
        } else if (leadMembers.length > 1) {
          error.lead = "leadSingle";
        } else if (written !== "" && roleKindOf(written, customRows) !== "lead") {
          // 队员类型当队长：服务端会静默回退成别的角色，这里直接拦截（提示语即「保存将被拒绝」）。
          error.lead = "notLeadKind";
        }
        errors.push(error);
      }
      return errors;
    }

    /** 团队错误表里被标红的字段数（0 = 可以提交）。 */
    function countTeamErrors(errors) {
      var count = 0;
      for (var i = 0; i < errors.length; i += 1) {
        var error = errors[i] || {};
        if (error.name !== "") count += 1;
        if (error.members !== "") count += 1;
        if (error.id !== "") count += 1;
        if (error.lead !== "") count += 1;
      }
      return count;
    }

    /**
     * 团队卡片标题：只认「字符串且去空白后非空」的 name，其余（"" / undefined / 纯空格 /
     * 非字符串）统一回退「未命名团队」。与角色标题同一口径——不能用 name 是否为空来猜，
     * 也不能把 undefined 直接渲染成空标题。
     */
    function teamTitle(team) {
      var name = team && typeof team.name === "string" ? team.name.trim() : "";
      return name !== "" ? name : null;
    }

    /** 角色是否主代理（co-orchestrator）：不绑定档位，工具由会话的 agent preset 决定。 */
    function isMainAgent(name) {
      return name === MAIN_AGENT_NAME;
    }

    /**
     * 档位标签的语义键：主代理走 "main"（专属文案），其余沿用 tier / unknown。
     * 渲染层拿它翻文案，纯函数层拿它做断言，两处口径不会漂。
     */
    function roleTierKey(detail) {
      if (isMainAgent(detail && detail.name)) return "main";
      return detail && detail.tierKnown === true ? detail.tier : "unknown";
    }

    /**
     * 成员候选：内置 16 角色 + customRoles（自定义与内置同名时不重复列出）。
     * customRoles 取「角色库」当前的编辑行，因此刚新建但未保存的角色也能先勾上。
     */
    function memberCandidates(customRows) {
      var builtin = [];
      for (var i = 0; i < BUILTIN_ROLE_NAMES.length; i += 1) builtin.push(BUILTIN_ROLE_NAMES[i]);
      var custom = [];
      var list = Array.isArray(customRows) ? customRows : [];
      for (var j = 0; j < list.length; j += 1) {
        var row = list[j] || {};
        var name = typeof row.name === "string" ? row.name : "";
        if (name === "" || builtin.indexOf(name) >= 0) continue;
        custom.push({ name: name, description: typeof row.description === "string" ? row.description : "" });
      }
      return { builtin: builtin, custom: custom };
    }

    /* ── 纯数据层：角色详情（档位 / 提示词 / 绑定工具），三处 UI 共用 ── */

    /**
     * 插件全名 → 短名。目录里写的是真实插件 id（dsh-tool-fs-search），
     * 窄卡片里只留工具段（fs-search），去掉 dsh-tool- / dsh- 前缀。
     */
    function pluginShortName(plugin) {
      var name = typeof plugin === "string" ? plugin : "";
      if (name.slice(0, 9) === "dsh-tool-") return name.slice(9);
      if (name.slice(0, 4) === "dsh-") return name.slice(4);
      return name;
    }

    /**
     * 档位的绑定工具清单（只读副本）。
     * 未知档位、目录缺字段、ROLE_CATALOG 缺失都返回空数组，绝不抛错。
     * @param tier - ro | ro-net | rw | rw-shell | cordis，或配置里写错的任意值。
     * @returns [{ plugin, pluginShort, label, note }]
     */
    function tierToolsOf(tier) {
      var tiers = ROLE_CATALOG && ROLE_CATALOG.tiers ? ROLE_CATALOG.tiers : {};
      var entry = typeof tier === "string" && Object.prototype.hasOwnProperty.call(tiers, tier) ? tiers[tier] : null;
      var list = entry && Array.isArray(entry.tools) ? entry.tools : [];
      var out = [];
      for (var i = 0; i < list.length; i += 1) {
        var tool = list[i] || {};
        out.push({
          plugin: typeof tool.plugin === "string" ? tool.plugin : "",
          pluginShort: pluginShortName(tool.plugin),
          label: typeof tool.label === "string" ? tool.label : "",
          note: typeof tool.note === "string" ? tool.note : ""
        });
      }
      return out;
    }

    /** 档位是否在 ROLE_CATALOG.tiers 里登记过（未知档位要优雅降级，不能裸值直显）。 */
    function tierKnown(tier) {
      var tiers = ROLE_CATALOG && ROLE_CATALOG.tiers ? ROLE_CATALOG.tiers : {};
      return typeof tier === "string" && tier !== "" && Object.prototype.hasOwnProperty.call(tiers, tier);
    }

    /**
     * 角色详情视图数据（纯函数，供角色库 / 团队成员 / 团队卡片共用）。
     *   内置角色 → ROLE_CATALOG.roles[name].brief（只读）
     *   自定义角色 → Config.customRoles[].prompt（只读）
     *   两者都没有 → tier/prompt 为空串、promptSource="none"，由 UI 显示未知角色文案。
     * @param name - 角色名（内置技能名或自定义角色名）。
     * @param customRows - 「角色库」当前编辑行（未保存的草稿也能查到）。
     * @param overrideRows - Config.roleOverrides（内置角色的字段级覆盖；缺省 = 全用内置默认）。
     */
    function roleDetailOf(name, customRows, overrideRows) {
      var roleName = typeof name === "string" ? name : "";
      var custom = null;
      var list = Array.isArray(customRows) ? customRows : [];
      for (var i = 0; i < list.length; i += 1) {
        var row = list[i] || {};
        if (roleName !== "" && row.name === roleName) {
          custom = row;
          break;
        }
      }
      var roles = ROLE_CATALOG && ROLE_CATALOG.roles ? ROLE_CATALOG.roles : {};
      var builtin = roleName !== "" && Object.prototype.hasOwnProperty.call(roles, roleName) ? roles[roleName] : null;
      var tier = "";
      var prompt = "";
      var description = "";
      var content = "";
      var source = "none";
      // 内置优先：校验层已禁止同名自定义角色（roleErrNameBuiltin），这里保持同一口径。
      if (builtin) {
        tier = typeof builtin.tier === "string" ? builtin.tier : "";
        prompt = typeof builtin.brief === "string" ? builtin.brief : "";
        description = typeof builtin.description === "string" ? builtin.description : "";
        // 完整技能正文（catalog 生成时写入）；自定义角色没有这份正文。
        content = typeof builtin.content === "string" ? builtin.content : "";
        source = "builtin";
      } else if (custom) {
        tier = typeof custom.tier === "string" ? custom.tier : "";
        prompt = typeof custom.prompt === "string" ? custom.prompt : "";
        description = typeof custom.description === "string" ? custom.description : "";
        source = "custom";
      }
      // 内置角色的字段级覆盖（Config.roleOverrides）：只影响展示，不夺权给自定义角色分支。
      var override = builtin ? findOverride(overrideRows, roleName) : null;
      var overridden = false;
      if (override !== null) {
        if (typeof override.tier === "string" && OVERRIDE_TIERS.indexOf(override.tier) >= 0) tier = override.tier;
        if (typeof override.prompt === "string" && override.prompt.trim() !== "") prompt = override.prompt;
        if (typeof override.description === "string") description = override.description;
        overridden = true;
      }
      var overrideTools = override && Array.isArray(override.tools) ? override.tools : null;
      var tools = overrideTools !== null && overrideTools.length > 0
        ? toolsFromIds(overrideTools)
        : tierToolsOf(tier);
      return {
        name: roleName,
        tier: tier,
        tierKnown: tierKnown(tier),
        toolCount: tools.length,
        tools: tools,
        prompt: prompt,
        promptSource: source,
        content: content,
        description: description,
        overridden: overridden,
        overrideTools: overrideTools
      };
    }

    /**
     * 角色类型解析（纯函数），优先级与运行时 src/roles.ts 的 resolveRoleKind **逐条对齐**：
     *   ① 自定义角色（角色库编辑行）里同名且 kind 合法 → 用它（同名覆盖内置）；
     *   ② ROLE_CATALOG.roles[name].kind（构建期从 BUILTIN_ROLE_KINDS 生成）；
     *   ③ 内置名单兜底（LEAD_ROLE_NAMES）→ 其余一律 "member"。
     * 未知角色 / 空名 / 脏值全部落到 "member"，与运行时一致，绝不抛错。
     *
     * @param name - 角色名
     * @param customRows - 角色库当前编辑行（未保存的草稿也算）
     * @returns "lead" | "member"
     */
    function roleKindOf(name, customRows) {
      var key = typeof name === "string" ? name.trim() : "";
      if (key === "") return "member";
      var list = Array.isArray(customRows) ? customRows : [];
      for (var i = 0; i < list.length; i += 1) {
        var row = list[i] || {};
        if (row.name !== key) continue;
        var customKind = roleKindValue(row.kind);
        if (customKind !== "") return customKind;
        break;
      }
      var roles = ROLE_CATALOG && ROLE_CATALOG.roles ? ROLE_CATALOG.roles : {};
      var entry = Object.prototype.hasOwnProperty.call(roles, key) ? roles[key] : null;
      var catalogKind = roleKindValue(entry && typeof entry === "object" ? entry.kind : "");
      if (catalogKind !== "") return catalogKind;
      return LEAD_ROLE_NAMES.indexOf(key) >= 0 ? "lead" : "member";
    }

    /**
     * 团队成员的档位分布：[{ tier, known, count }]，按 ROLE_TIERS 顺序，未知档位收尾。
     * 成员名查不到角色时归入 tier="unknown"，不会因为配置里多写一个名字而崩。
     */
    function tierDistributionOf(members, customRows, overrideRows) {
      var counts = {};
      var list = Array.isArray(members) ? members : [];
      for (var i = 0; i < list.length; i += 1) {
        var detail = roleDetailOf(list[i], customRows, overrideRows);
        var key = roleTierKey(detail) === "main" ? "main" : detail.tierKnown ? detail.tier : "unknown";
        counts[key] = Object.prototype.hasOwnProperty.call(counts, key) ? counts[key] + 1 : 1;
      }
      var sorted = [];
      for (var t = 0; t < ROLE_TIERS.length; t += 1) {
        if (Object.prototype.hasOwnProperty.call(counts, ROLE_TIERS[t])) {
          sorted.push({ tier: ROLE_TIERS[t], known: true, count: counts[ROLE_TIERS[t]] });
        }
      }
      if (Object.prototype.hasOwnProperty.call(counts, "main")) {
        sorted.unshift({ tier: "main", known: true, count: counts.main });
      }
      if (Object.prototype.hasOwnProperty.call(counts, "unknown")) {
        sorted.push({ tier: "unknown", known: false, count: counts.unknown });
      }
      return sorted;
    }

    /* ── 极简 observable store（uSES：快照未变必须返回同一引用） ──── */

    function createStateStore(initial) {
      var current = initial;
      var listeners = [];
      return {
        getSnapshot: function () {
          return current;
        },
        subscribe: function (listener) {
          listeners.push(listener);
          return function () {
            var index = listeners.indexOf(listener);
            if (index >= 0) listeners.splice(index, 1);
          };
        },
        set: function (next) {
          if (next === current) return;
          current = next;
          var snapshot = listeners.slice();
          for (var i = 0; i < snapshot.length; i += 1) {
            try {
              snapshot[i]();
            } catch (error) {
              /* 单个订阅者异常不阻断其他订阅者 */
            }
          }
        }
      };
    }

    var EMPTY_STATE = Object.freeze({
      status: "loading",
      writable: false,
      dirty: false,
      conflicted: false,
      saving: false,
      saved: false,
      failed: false,
      rows: [],
      providers: [],
      modelsByProvider: {},
      // effortsByModel[provider][modelId] = [{ id, label }]；模型不支持推理强度时该键缺失。
      effortsByModel: {},
      catalogStatus: "loading",
      catalogError: "",
      roles: [],
      rolesDirty: false,
      rolesSaved: false,
      rolesFailed: false,
      roleErrors: [],
      teams: [],
      activeTeam: "",
      teamsDirty: false,
      teamsSaved: false,
      teamsFailed: false,
      teamErrors: [],
      teamsNotice: "",
      expandedTeam: -1,
      // 队长提示词预览展开的是哪个团队行下标；-1 = 全收起（折叠区默认收起）。
      teamPreview: -1,
      // 角色详情面板（提示词 + 绑定工具）展开的是哪个角色名；"" = 全收起。
      expandedRole: "",
      // 设置页 tab 选中态（"teams" | "roles"）：只活在 controller 闭包里，不写配置。
      tab: "teams",
      // 默认预设（remote.agentPresets.list 里 isDefault=true 的那一项）；取不到时 null。
      presetStatus: "loading",
      presetDefault: null
    });

    /**
     * 把 configForms 的一个 ConfigForm 与模型目录合成一个带草稿的页面控制器。
     * @param ctx - 客户端 cordis 上下文（remote / locale）。
     * @param scope - ctx.configForms.get(ENTRY_ID)，可能为 null（宿主未提供服务）。
     * @returns { store, start, dispose, editRow, resetRow, discard, save, loadCatalog }
     */
    function buildSkillsController(ctx, scope) {
      var store = createStateStore(null);

      var draft = null;               // { rows, revision }
      var conflicted = false;
      var saving = false;
      var saved = false;
      var failed = false;
      var disposed = false;

      var catalogStatus = "loading";
      var catalogError = "";
      var catalogProviders = [];
      var catalogByProvider = {};
      // effortsByModel[provider][modelId] = [{ id, label }]，与 modelsByProvider 同批构建。
      var catalogEfforts = {};
      var catalogGeneration = 0;

      var lastValue;
      var lastRows = [];
      var lastRoles = [];
      var lastTeams = [];
      var lastActiveTeam = "";
      var lastOverrides = [];
      var published = null;

      // 设置页 tab 选中态：和草稿一样只活在 controller 闭包里，靠既有的 store 通知通道
      // 触发重渲染。不放进 React 组件状态——宿主可能以直接函数调用方式渲染组件，
      // 组件体内的任何 hook 都会抛 Invalid hook call，进而让整个设置节注册失败。
      var tab = "teams";

      // 角色库搜索关键词：同样只活在 controller 闭包里（不写配置、不是 hook），
      // 只用于过滤渲染，清空即恢复全部。
      var roleSearch = "";

      /** 切换设置页 tab：先归一（脏值回落 teams），变了才写闭包态并发布一次。 */
      function setTab(next) {
        var normalized = normalizeTab(next);
        if (normalized === tab) return;
        tab = normalized;
        publish();
      }

      /** 角色库搜索：值变了才发布（输入框每敲一个字符都会走到这里）。 */
      function setRoleSearch(next) {
        var normalized = typeof next === "string" ? next : "";
        if (normalized === roleSearch) return;
        roleSearch = normalized;
        publish();
      }

      // 自定义角色草稿与 skills 草稿各自独立（写的是不同 path），但共用同一 scope、
      // 同一 revision 冲突判定和同一个 saving 互斥位。roleErrors 与行等长，空串 = 合法。
      var rolesDraft = null;          // { rows, revision }
      var rolesSaved = false;
      var rolesFailed = false;
      var roleErrors = [];
      // 每行「从哪个模板来」：下标与角色行一一对应，"" = 未选/空白角色。
      // 只存在于本次编辑会话（Config.customRoles 里没有该字段，保存时不写）。
      var roleTemplates = [];
      var rolePicker = -1;            // 当前展开模板选择器的行下标，-1 = 全收起
      // 内置角色的编辑草稿：{ name, description, prompt, tier, tools, revision }。
      // 只活在本次编辑会话（Config.roleOverrides 里没有草稿标记，保存时只写差异）。
      var builtinEdit = null;
      var builtinEditNotice = "";     // "" | "saved" | "failed" | "tierInvalid"
      var builtinEditNoticeName = ""; // notice 归属的角色名（面板收起后仍能显示一次）

      /** 模板标记数组对齐到角色行数（新增/删除行后补齐或截断）。 */
      function syncRoleTemplates(size) {
        var out = [];
        for (var i = 0; i < size; i += 1) out.push(i < roleTemplates.length ? roleTemplates[i] : "");
        roleTemplates = out;
      }

      // 团队草稿：只写 path:["teams"]（Config.activeTeam 已废弃，本页不再写入）。
      var teamsDraft = null;          // { rows, revision }
      var teamsSaved = false;
      var teamsFailed = false;
      var teamErrors = [];
      var teamsNotice = "";           // 一次性提示（保留 "activeCleared" 旧词条，本版不再触发）
      var teamMemberNotice = null;    // 成员勾选被拒的一次性提示 { index, code, name }（null = 无）
      var expandedTeam = -1;          // 展开编辑的团队行下标，-1 = 全收起
      var teamPreview = -1;           // 展开队长提示词预览的团队行下标，-1 = 全收起
      var expandedRole = "";          // 展开详情的角色名，"" = 全收起（角色库/成员/团队三处共用）

      // 默认预设（会话未指名预设时组合的那一个）：客户端拿不到「当前会话」的预设，
      // 只能通过 remote 的 agentPresets.list 取默认项。取不到就静默降级成未知文案。
      var presetStatus = "loading";   // "loading" | "ready" | "unknown"
      var presetDefault = null;       // { id, name }
      var presetLoaded = false;       // 成功取到过就不再重复请求（缓存失效前只用一份）
      var presetGeneration = 0;

      /**
       * 取 agentPresets.list 的可调用入口：优先 `remote.agentPresets.list()`（服务/方法两段），
       * 退到扁平 key 与通用 `remote.call`。三处都没有就返回 null（当作拿不到）。
       *
       * 注意：宿主未把 `remote.agentPresets` 纳入注入时，cordis 的 remote proxy 在**属性读取**
       * 那一刻就抛错，所以整个探测必须包在 try/catch 里，读取失败一律降级成 null。
       */
      function agentPresetRequest() {
        try {
          var remote = ctx && ctx.remote;
          if (!remote || typeof remote !== "object") return null;
          var service = remote.agentPresets;
          if (service && typeof service.list === "function") return function () { return service.list(); };
          var flat = remote["agentPresets/list"];
          if (typeof flat === "function") return function () { return flat(); };
          if (typeof remote.call === "function") return function () { return remote.call("agentPresets/list"); };
          return null;
        } catch (error) {
          return null;
        }
      }

      /** 从各种可能的返回形状里取出预设数组：{ ok, value: { presets } } / { presets } / 数组。 */
      function agentPresetRowsOf(response) {
        if (!response || typeof response !== "object") return null;
        if (Array.isArray(response)) return response;
        var value = response.ok === true && response.value !== undefined ? response.value : response;
        if (!value || typeof value !== "object") return null;
        if (Array.isArray(value)) return value;
        if (Array.isArray(value.presets)) return value.presets;
        return null;
      }

      function applyPresetRows(rows) {
        var found = null;
        var list = Array.isArray(rows) ? rows : [];
        for (var i = 0; i < list.length; i += 1) {
          var row = list[i];
          if (!row || typeof row !== "object" || row.isDefault !== true) continue;
          found = {
            id: typeof row.id === "string" ? row.id : "",
            name: typeof row.name === "string" ? row.name : ""
          };
          break;
        }
        presetStatus = found === null ? "unknown" : "ready";
        presetDefault = found;
      }

      /**
       * 异步取默认预设并缓存；任何失败（无 remote / 抛错 / 形状不认识）都静默降级成「未知」，
       * 不抛、不弹错误、不阻断其余页面。
       */
      function loadPresets() {
        if (disposed || presetLoaded) return;
        presetGeneration += 1;
        var generation = presetGeneration;
        var request = agentPresetRequest();
        if (request === null) {
          presetStatus = "unknown";
          presetDefault = null;
          publish();
          return;
        }
        var response;
        try {
          response = request();
        } catch (error) {
          presetStatus = "unknown";
          presetDefault = null;
          publish();
          return;
        }
        Promise.resolve(response).then(function (result) {
          if (disposed || generation !== presetGeneration) return;
          var rows = agentPresetRowsOf(result);
          if (rows === null) {
            presetStatus = "unknown";
            presetDefault = null;
            publish();
            return;
          }
          applyPresetRows(rows);
          presetLoaded = presetStatus === "ready";
          publish();
        }, function () {
          if (disposed || generation !== presetGeneration) return;
          presetStatus = "unknown";
          presetDefault = null;
          publish();
        });
      }

      function readScope() {
        if (!scope || typeof scope.getSnapshot !== "function") {
          return { status: "unavailable", writable: false, value: undefined, revision: undefined };
        }
        try {
          var snapshot = scope.getSnapshot();
          return snapshot && typeof snapshot === "object" ? snapshot : { status: "loading", writable: false };
        } catch (error) {
          return { status: "unavailable", writable: false };
        }
      }

      /** 快照 value 变了一次就把 skills 与 customRoles 两份编辑行一起重算（共用同一引用判断）。 */
      function refreshFromValue() {
        var snapshot = readScope();
        if (snapshot.value === lastValue) return;
        lastValue = snapshot.value;
        lastRows = displayRows(rowsFromSkills(snapshot.value && snapshot.value.skills));
        lastRoles = rowsFromCustomRoles(snapshot.value && snapshot.value.customRoles);
        lastTeams = rowsFromTeams(snapshot.value && snapshot.value.teams);
        lastOverrides = rowsFromOverrides(snapshot.value && snapshot.value.roleOverrides);
        lastActiveTeam = snapshot.value && typeof snapshot.value.activeTeam === "string" ? snapshot.value.activeTeam : "";
      }

      function currentRows() {
        refreshFromValue();
        return lastRows;
      }

      function currentRoles() {
        refreshFromValue();
        return lastRoles;
      }

      function currentTeams() {
        refreshFromValue();
        return lastTeams;
      }

      function currentOverrides() {
        refreshFromValue();
        return lastOverrides;
      }

      function currentActiveTeam() {
        refreshFromValue();
        return lastActiveTeam;
      }

      function buildState() {
        var snapshot = readScope();
        return {
          status: snapshot.status || "loading",
          writable: snapshot.status === "ready" && snapshot.writable === true,
          dirty: draft !== null,
          conflicted: conflicted,
          saving: saving,
          saved: saved,
          failed: failed,
          rows: draft !== null ? draft.rows : currentRows(),
          providers: catalogProviders,
          modelsByProvider: catalogByProvider,
          effortsByModel: catalogEfforts,
          catalogStatus: catalogStatus,
          catalogError: catalogError,
          roles: rolesDraft !== null ? rolesDraft.rows : currentRoles(),
          rolesDirty: rolesDraft !== null,
          rolesSaved: rolesSaved,
          rolesFailed: rolesFailed,
          roleErrors: roleErrors,
          roleTemplates: roleTemplates,
          rolePicker: rolePicker,
          roleSearch: roleSearch,
          overrides: currentOverrides(),
          builtinEdit: builtinEdit,
          builtinEditNotice: builtinEditNotice,
          builtinEditNoticeName: builtinEditNoticeName,
          teams: teamsDraft !== null ? teamsDraft.rows : currentTeams(),
          activeTeam: currentActiveTeam(),
          teamsDirty: teamsDraft !== null,
          teamsSaved: teamsSaved,
          teamsFailed: teamsFailed,
          teamErrors: teamErrors,
          teamsNotice: teamsNotice,
          teamMemberNotice: teamMemberNotice,
          expandedTeam: expandedTeam,
          teamPreview: teamPreview,
          expandedRole: expandedRole,
          tab: tab,
          presetStatus: presetStatus,
          presetDefault: presetDefault
        };
      }

      function sameState(left, right) {
        if (left === null || left === undefined || right === null || right === undefined) return false;
        return left.status === right.status
          && left.writable === right.writable
          && left.dirty === right.dirty
          && left.conflicted === right.conflicted
          && left.saving === right.saving
          && left.saved === right.saved
          && left.failed === right.failed
          && left.rows === right.rows
          && left.providers === right.providers
          && left.modelsByProvider === right.modelsByProvider
          && left.effortsByModel === right.effortsByModel
          && left.catalogStatus === right.catalogStatus
          && left.catalogError === right.catalogError
          && left.roles === right.roles
          && left.rolesDirty === right.rolesDirty
          && left.rolesSaved === right.rolesSaved
          && left.rolesFailed === right.rolesFailed
          && left.roleErrors === right.roleErrors
          && left.roleTemplates === right.roleTemplates
          && left.rolePicker === right.rolePicker
          && left.roleSearch === right.roleSearch
          && left.overrides === right.overrides
          && left.builtinEdit === right.builtinEdit
          && left.builtinEditNotice === right.builtinEditNotice
          && left.builtinEditNoticeName === right.builtinEditNoticeName
          && left.teams === right.teams
          && left.activeTeam === right.activeTeam
          && left.teamsDirty === right.teamsDirty
          && left.teamsSaved === right.teamsSaved
          && left.teamsFailed === right.teamsFailed
          && left.teamErrors === right.teamErrors
          && left.teamsNotice === right.teamsNotice
          && left.teamMemberNotice === right.teamMemberNotice
          && left.expandedTeam === right.expandedTeam
          && left.teamPreview === right.teamPreview
          && left.expandedRole === right.expandedRole
          && left.tab === right.tab
          && left.presetStatus === right.presetStatus
          && left.presetDefault === right.presetDefault;
      }

      function publish() {
        if (disposed) return;
        var next = buildState();
        if (sameState(published, next)) return;
        published = next;
        store.set(next);
      }

      function onScopeChange() {
        if (disposed) return;
        // 自己的写入进行中不做冲突判定：revision 变化正是本次写入引起的。
        if (!saving && (draft !== null || rolesDraft !== null)) {
          var snapshot = readScope();
          if (draft !== null && snapshot.revision !== draft.revision) conflicted = true;
          if (rolesDraft !== null && snapshot.revision !== rolesDraft.revision) conflicted = true;
          if (teamsDraft !== null && snapshot.revision !== teamsDraft.revision) conflicted = true;
        }
        publish();
      }

      function beginDraft() {
        if (draft !== null) return draft;
        var snapshot = readScope();
        var rows = [];
        var source = currentRows();
        for (var i = 0; i < source.length; i += 1) rows.push(copyRow(source[i]));
        draft = { rows: rows, revision: snapshot.revision };
        return draft;
      }

      function beginRolesDraft() {
        if (rolesDraft !== null) return rolesDraft;
        var snapshot = readScope();
        var source = currentRoles();
        var rows = [];
        for (var i = 0; i < source.length; i += 1) rows.push(copyRole(source[i]));
        syncRoleTemplates(rows.length);
        rolesDraft = { rows: rows, revision: snapshot.revision };
        return rolesDraft;
      }

      function canEdit() {
        if (disposed || saving || conflicted) return false;
        var snapshot = readScope();
        return snapshot.status === "ready" && snapshot.writable === true;
      }

      /** 某 provider+model 支持的推理档位 id 列表（目录未就绪或模型不支持时为空数组）。 */
      function effortIdsFor(provider, model) {
        if (provider === "" || model === "") return [];
        var byModel = catalogEfforts[provider];
        if (!byModel) return [];
        var list = byModel[model];
        if (!Array.isArray(list)) return [];
        var ids = [];
        for (var i = 0; i < list.length; i += 1) ids.push(list[i].id);
        return ids;
      }

      /**
       * 换供应商/模型后，已选强度若不在新模型的档位里就清空（避免写出必然被宿主拒的配置：
       * delegate 侧对不支持的档位会 UNSUPPORTED_REASONING_EFFORT）。
       * 档位未知（目录未就绪 / 手填 model / 模型不支持）时也清空——此时无法证明该强度仍有效。
       */
      function reconcileEffort(provider, model, effort) {
        if (effort === "") return "";
        var ids = effortIdsFor(provider, model);
        return ids.indexOf(effort) >= 0 ? effort : "";
      }

      function editRow(name, field, value) {
        if (field !== "provider" && field !== "model" && field !== "reasoningEffort") return;
        if (!canEdit()) return;
        var current = beginDraft();
        var next = [];
        var changed = false;
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          if (row.name !== name) {
            next.push(row);
            continue;
          }
          if (field === "provider") {
            if (row.provider === value) {
              next.push(row);
              continue;
            }
            // 换供应商后旧 model 一定属于旧目录，留着只会写出失效路由；
            // 推理档位属于「供应商+模型」这一对，也一并清空。
            next.push({
              name: row.name,
              provider: value,
              model: "",
              reasoningEffort: "",
              extra: row.extra
            });
            changed = true;
          } else if (field === "model") {
            if (row.model === value) {
              next.push(row);
              continue;
            }
            next.push({
              name: row.name,
              provider: row.provider,
              model: value,
              reasoningEffort: reconcileEffort(row.provider, value, effortOf(row)),
              extra: row.extra
            });
            changed = true;
          } else {
            if (effortOf(row) === value) {
              next.push(row);
              continue;
            }
            next.push({
              name: row.name,
              provider: row.provider,
              model: row.model,
              reasoningEffort: value,
              extra: row.extra
            });
            changed = true;
          }
        }
        if (!changed) return;
        draft.rows = next;
        saved = false;
        failed = false;
        publish();
      }

      function resetRow(name) {
        if (!canEdit()) return;
        var current = beginDraft();
        var next = [];
        var changed = false;
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          if (row.name !== name) {
            next.push(row);
            continue;
          }
          if (row.provider === "" && row.model === "" && effortOf(row) === "") {
            next.push(row);
            continue;
          }
          // 只清 provider/model/reasoningEffort：maxTokens 等页面不展示的字段留着，
          // 避免重置后静默丢配置。
          next.push({
            name: row.name,
            provider: "",
            model: "",
            reasoningEffort: "",
            extra: row.extra
          });
          changed = true;
        }
        if (!changed) return;
        draft.rows = next;
        saved = false;
        failed = false;
        publish();
      }

      function discard() {
        if (saving) return;
        draft = null;
        conflicted = false;
        saved = false;
        failed = false;
        publish();
      }

      function save() {
        if (disposed || saving || draft === null) return Promise.resolve(false);
        var snapshot = readScope();
        if (snapshot.status !== "ready" || snapshot.writable !== true || conflicted) return Promise.resolve(false);
        if (draft.revision !== undefined && snapshot.revision !== draft.revision) {
          conflicted = true;
          publish();
          return Promise.resolve(false);
        }
        var expected = draft.revision;
        var next = rowsToSkills(draft.rows);
        saving = true;
        saved = false;
        failed = false;
        publish();
        var request;
        try {
          request = scope.mutate([{ op: "set", path: ["skills"], value: next }], expected);
        } catch (error) {
          saving = false;
          failed = true;
          publish();
          return Promise.resolve(false);
        }
        return Promise.resolve(request).then(function (accepted) {
          if (disposed) return false;
          saving = false;
          if (accepted === true) {
            draft = null;
            conflicted = false;
            failed = false;
            saved = true;
            lastValue = undefined;
          } else {
            failed = true;
          }
          publish();
          return accepted === true;
        }, function () {
          if (disposed) return false;
          saving = false;
          failed = true;
          publish();
          return false;
        });
      }

      /**
       * 改一行的某个字段（name / description / prompt / tier / tools）。
       * 只写受控字段，避免把 Config 里别的键带歪；提交过校验后改字段会即时重算标红。
       * tools 传整数组（checkbox 勾选结果），一次性替换。
       */
      function editRole(index, field, value) {
        if (field !== "name" && field !== "description" && field !== "prompt" && field !== "tier" && field !== "tools") return;
        if (!canEdit()) return;
        var current = beginRolesDraft();
        if (index < 0 || index >= current.rows.length) return;
        if (field === "tools") {
          var picked = [];
          var list = Array.isArray(value) ? value : [];
          for (var t = 0; t < list.length; t += 1) {
            if (typeof list[t] === "string" && list[t] !== "" && picked.indexOf(list[t]) < 0) picked.push(list[t]);
          }
          value = picked;
        } else if (current.rows[index][field] === value) {
          return;
        }
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          var copy = copyRole(current.rows[i]);
          if (i === index) copy[field] = value;
          next.push(copy);
        }
        rolesDraft.rows = next;
        roleErrors = roleErrors.length > 0 ? validateRoles(next) : [];
        rolesSaved = false;
        rolesFailed = false;
        publish();
      }

      /**
       * 用模板填一行：name（加 -copy 防重名）/ description / prompt（brief 全文）/ tier / tools。
       * 空白角色（id=""）只清空字段，名字留给用户自己填。
       */
      function chooseTemplate(index, templateId) {
        if (!canEdit()) return;
        var template = templateOf(templateId);
        if (template === null) return;
        var current = beginRolesDraft();
        if (index < 0 || index >= current.rows.length) return;
        var taken = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          if (i !== index && current.rows[i].name !== "") taken.push(current.rows[i].name);
        }
        for (var b = 0; b < BUILTIN_ROLE_NAMES.length; b += 1) taken.push(BUILTIN_ROLE_NAMES[b]);
        var next = [];
        for (var j = 0; j < current.rows.length; j += 1) {
          var copy = copyRole(current.rows[j]);
          if (j === index) {
            if (template.blank) {
              copy.name = "";
              copy.description = "";
              copy.prompt = "";
              copy.tier = "ro";
              // 空白角色默认不选类型：类型是必填项，必须由用户手动选。
              copy.kind = "";
              copy.tools = [];
            } else {
              // 「基于模板」的显示名固定用模板 id：选完再改名也不影响这条提示。
              copy.name = templateRoleName(template.name, taken);
              copy.description = template.description !== "" ? template.description : template.name;
              copy.prompt = template.brief !== "" ? template.brief : template.description;
              copy.tier = ROLE_TIERS.indexOf(template.tier) >= 0 ? template.tier : "ro";
              copy.kind = roleKindValue(template.kind) !== "" ? template.kind : "member";
              copy.tools = template.tools.slice();
            }
          }
          next.push(copy);
        }
        var marks = [];
        for (var k = 0; k < next.length; k += 1) marks.push(k === index ? template.id : roleTemplates[k]);
        rolesDraft.rows = next;
        syncRoleTemplates(next.length);
        roleTemplates = marks;
        rolePicker = -1;
        roleErrors = roleErrors.length > 0 ? validateRoles(next) : [];
        rolesSaved = false;
        rolesFailed = false;
        publish();
      }

      /** 档位退化为快捷组合：点一下按 ROLE_CATALOG.tiers[tier].tools 批量勾选，返回勾上的 id。 */
      function applyTierTools(index) {
        if (!canEdit()) return [];
        var current = beginRolesDraft();
        if (index < 0 || index >= current.rows.length) return [];
        var ids = tierToolIds(current.rows[index].tier);
        editRole(index, "tools", ids);
        return ids;
      }

      /**
       * 角色卡片 / 内置卡片的模型区：按角色名写 Config.skills（**不是 customRoles**）。
       * 行不存在就先建一行；provider / model / reasoningEffort 与上方代理行同一套语义，
       * maxTokens（最大输出）落在 extra 里由 rowsToSkills 原样保留。
       */
      function editSkillRow(name, field, value) {
        if (field !== "provider" && field !== "model" && field !== "reasoningEffort" && field !== "maxTokens") return;
        if (!canEdit() || typeof name !== "string" || name === "") return;
        var current = beginDraft();
        var next = [];
        var found = false;
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          if (row.name !== name) {
            next.push(row);
            continue;
          }
          found = true;
          var copy = copyRow(row);
          applySkillField(copy, field, value);
          next.push(copy);
        }
        if (!found) {
          var created = emptyRow(name);
          applySkillField(created, field, value);
          next.push(created);
        }
        draft.rows = next;
        saved = false;
        failed = false;
        publish();
      }

      /** 单行改字段：换供应商连带清 model/effort（与 editRow 同口径，避免写出失效路由）。 */
      function applySkillField(row, field, value) {
        if (field === "provider") {
          row.provider = value;
          row.model = "";
          row.reasoningEffort = "";
          return;
        }
        if (field === "model") {
          row.model = value;
          row.reasoningEffort = reconcileEffort(row.provider, value, effortOf(row));
          return;
        }
        if (field === "reasoningEffort") {
          row.reasoningEffort = value;
          return;
        }
        var raw = value === undefined || value === null ? "" : String(value).trim();
        if (raw === "") {
          if (row.extra) delete row.extra.maxTokens;
          return;
        }
        var number = Number(raw);
        if (!isFinite(number) || number < 1) return;
        if (!row.extra) row.extra = {};
        row.extra.maxTokens = Math.round(number);
      }

      /** 恢复默认：清供应商 / 模型 / 推理强度 / 最大输出四项，其余未知字段保留。 */
      function resetSkillRow(name) {
        if (!canEdit() || typeof name !== "string" || name === "") return;
        var current = beginDraft();
        var next = [];
        var changed = false;
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          if (row.name !== name) {
            next.push(row);
            continue;
          }
          if (row.provider === "" && row.model === "" && effortOf(row) === "" && row.extra.maxTokens === undefined) {
            next.push(row);
            continue;
          }
          var copy = copyRow(row);
          copy.provider = "";
          copy.model = "";
          copy.reasoningEffort = "";
          delete copy.extra.maxTokens;
          next.push(copy);
          changed = true;
        }
        if (!changed) return;
        draft.rows = next;
        saved = false;
        failed = false;
        publish();
      }

      /** 添加角色：先展开「选择一个模板开始」，选中模板后自动填字段。 */
      function addRole() {
        if (!canEdit()) return;
        var current = beginRolesDraft();
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) next.push(copyRole(current.rows[i]));
        next.push(emptyRole());
        rolesDraft.rows = next;
        syncRoleTemplates(next.length);
        rolePicker = next.length - 1;
        roleErrors = [];
        rolesSaved = false;
        rolesFailed = false;
        publish();
      }

      /** 删掉一行。删空后保存即写回 []，运行时注册器会移除这些角色。 */
      function removeRole(index) {
        if (!canEdit()) return;
        var current = beginRolesDraft();
        if (index < 0 || index >= current.rows.length) return;
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          if (i !== index) next.push(current.rows[i]);
        }
        var marks = [];
        for (var m = 0; m < roleTemplates.length; m += 1) if (m !== index) marks.push(roleTemplates[m]);
        roleTemplates = marks;
        syncRoleTemplates(next.length);
        if (rolePicker === index) rolePicker = -1;
        else if (rolePicker > index) rolePicker -= 1;
        rolesDraft.rows = next;
        roleErrors = [];
        rolesSaved = false;
        rolesFailed = false;
        publish();
      }

      /**
       * 「另存为副本」：以当前行字段生成一条新的自定义角色草稿（name 加 -copy 并消歧）。
       * 只写草稿（保存后随机整表写回 Config.customRoles），模板标记沿用原行的来源。
       */
      function duplicateRole(index) {
        if (!canEdit()) return;
        var current = beginRolesDraft();
        if (index < 0 || index >= current.rows.length) return;
        var source = current.rows[index];
        var taken = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          if (typeof current.rows[i].name === "string" && current.rows[i].name !== "") taken.push(current.rows[i].name);
        }
        for (var b = 0; b < BUILTIN_ROLE_NAMES.length; b += 1) taken.push(BUILTIN_ROLE_NAMES[b]);
        var copy = copyRole(source);
        copy.name = templateRoleName(source.name, taken);
        var next = [];
        for (var j = 0; j < current.rows.length; j += 1) next.push(copyRole(current.rows[j]));
        next.push(copy);
        var marks = [];
        for (var m = 0; m < roleTemplates.length; m += 1) marks.push(roleTemplates[m]);
        syncRoleTemplates(next.length);
        for (var s = 0; s < marks.length; s += 1) roleTemplates[s] = marks[s];
        roleTemplates[next.length - 1] = index < roleTemplates.length ? roleTemplates[index] : "";
        rolesDraft.rows = next;
        roleErrors = roleErrors.length > 0 ? validateRoles(next) : [];
        rolePicker = -1;
        rolesSaved = false;
        rolesFailed = false;
        publish();
      }

      /**
       * 「去编辑」（团队成员详情 → 角色 tab）：切到角色 tab、确保该角色详情展开，
       * 并收起团队编辑区（teamIndex 有效时）。纯 UI 状态，不写配置。
       */
      function focusRoleEditor(name, teamIndex) {
        var key = typeof name === "string" ? name.trim() : "";
        if (key !== "") expandedRole = key;
        if (typeof teamIndex === "number" && expandedTeam === teamIndex) expandedTeam = -1;
        tab = "roles";
        publish();
      }

      function discardRoles() {
        if (saving) return;
        rolesDraft = null;
        roleTemplates = [];
        rolePicker = -1;
        rolesSaved = false;
        rolesFailed = false;
        roleErrors = [];
        publish();
      }

      /** 展开/收起某行的模板选择器。 */
      function toggleRolePicker(index) {
        rolePicker = rolePicker === index ? -1 : index;
        publish();
      }

      /**
       * 内置角色卡「以此模板新建」：加一行自定义角色草稿，再用该内置角色的
       * description / brief / tier / tools / kind 预填（name 加 -copy 后缀并自动消歧）。
       * 与「编辑」不同：这里写的是 Config.customRoles，不动 Config.roleOverrides。
       */
      function newRoleFromTemplate(templateId) {
        if (!canEdit()) return;
        addRole();
        if (rolesDraft === null || rolesDraft.rows.length === 0) return;
        var index = rolesDraft.rows.length - 1;
        chooseTemplate(index, templateId);
      }

      /**
       * 整表写回 Config.customRoles（数组字段整体替换，与 skills 同一 mutate 契约）。
       * 校验不通过只标红、不发请求；成功后运行时注册器约 1 秒内热加载，无需重启。
       */
      function saveRoles() {
        if (disposed || saving || rolesDraft === null) return Promise.resolve(false);
        var snapshot = readScope();
        if (snapshot.status !== "ready" || snapshot.writable !== true || conflicted) return Promise.resolve(false);
        if (rolesDraft.revision !== undefined && snapshot.revision !== rolesDraft.revision) {
          conflicted = true;
          publish();
          return Promise.resolve(false);
        }
        var errors = validateRoles(rolesDraft.rows);
        if (countRoleErrors(errors) > 0) {
          roleErrors = errors;
          rolesSaved = false;
          rolesFailed = false;
          publish();
          return Promise.resolve(false);
        }
        var expected = rolesDraft.revision;
        var next = rolesToCustomRoles(rolesDraft.rows);
        saving = true;
        rolesSaved = false;
        rolesFailed = false;
        roleErrors = [];
        publish();
        var request;
        try {
          request = scope.mutate([{ op: "set", path: ["customRoles"], value: next }], expected);
        } catch (error) {
          saving = false;
          rolesFailed = true;
          publish();
          return Promise.resolve(false);
        }
        return Promise.resolve(request).then(function (accepted) {
          if (disposed) return false;
          saving = false;
          if (accepted === true) {
            rolesDraft = null;
            rolesFailed = false;
            rolesSaved = true;
            lastValue = undefined;
          } else {
            rolesFailed = true;
          }
          publish();
          return accepted === true;
        }, function () {
          if (disposed) return false;
          saving = false;
          rolesFailed = true;
          publish();
          return false;
        });
      }

      /* ── 团队：Config.teams + Config.activeTeam ──────────────────── */

      function beginTeamsDraft() {
        if (teamsDraft !== null) return teamsDraft;
        var snapshot = readScope();
        var source = currentTeams();
        var rows = [];
        for (var i = 0; i < source.length; i += 1) rows.push(copyTeam(source[i]));
        teamsDraft = { rows: rows, revision: snapshot.revision };
        return teamsDraft;
      }

      /** 除第 index 行以外已被占用的团队 id / slug（自动消歧用：别人手填的 slug 也算占用）。 */
      function takenIdsExcept(rows, index) {
        var out = [];
        for (var i = 0; i < rows.length; i += 1) {
          if (i === index) continue;
          if (typeof rows[i].id === "string" && rows[i].id !== "") out.push(rows[i].id);
          var slug = teamSlugOf(rows[i]);
          if (slug !== "" && out.indexOf(slug) < 0) out.push(slug);
        }
        return out;
      }

      /** 写回草稿行并（按需）重算标红；任何编辑都会清掉「已保存」状态。 */
      function pushTeamsRows(rows) {
        teamsDraft.rows = rows;
        teamErrors = teamErrors.length > 0 ? validateTeams(rows, currentRoles()) : [];
        teamsSaved = false;
        teamsFailed = false;
        teamsNotice = "";
        teamMemberNotice = null;
        publish();
      }

      /** 单击卡片头部展开/收起编辑区（纯 UI 状态，不进配置）。 */
      function toggleTeam(index) {
        expandedTeam = expandedTeam === index ? -1 : index;
        publish();
      }

      /** 展开/收起「队长提示词预览」折叠区（纯 UI 状态；文本本身总是按当前行实时重算）。 */
      function toggleTeamPreview(index) {
        teamPreview = teamPreview === index ? -1 : index;
        publish();
      }

      /**
       * 展开/收起某个角色的详情面板（档位 + 提示词 + 绑定工具）。
       * 纯 UI 状态、不写配置：角色库卡片、团队成员、团队卡片点开的都是同一份面板。
       */
      function toggleRoleDetail(name) {
        var key = typeof name === "string" ? name : "";
        expandedRole = expandedRole === key ? "" : key;
        publish();
      }

      /* ── 内置角色：Config.roleOverrides（提示词 / 档位 / 工具的字段级覆盖） ── */

      /** 记一次一次性提示（绑定角色名，面板收起后卡片上仍能看到结果）。 */
      function setBuiltinNotice(name, kind) {
        builtinEditNoticeName = typeof name === "string" ? name : "";
        builtinEditNotice = typeof kind === "string" ? kind : "";
      }

      /** 打开内置角色编辑面板：字段初值 = 内置默认 + 现有 override 的合并结果。 */
      function beginBuiltinEdit(name) {
        var key = typeof name === "string" ? name.trim() : "";
        var base = key !== "" ? builtinRoleOf(key) : null;
        if (base === null) return;
        var override = findOverride(currentOverrides(), key);
        var tier = override && typeof override.tier === "string" && OVERRIDE_TIERS.indexOf(override.tier) >= 0
          ? override.tier
          : (typeof base.tier === "string" ? base.tier : "");
        var overrideTools = override && Array.isArray(override.tools) ? normalizeToolIds(override.tools) : [];
        builtinEdit = {
          name: key,
          description: override && typeof override.description === "string"
            ? override.description
            : (typeof base.description === "string" ? base.description : ""),
          prompt: override && typeof override.prompt === "string" && override.prompt.trim() !== ""
            ? override.prompt
            : (typeof base.brief === "string" ? base.brief : ""),
          tier: tier,
          tools: overrideTools.length > 0 ? overrideTools : toolIdsOfTier(tier),
          revision: readScope().revision
        };
        setBuiltinNotice(key, "");
        expandedRole = "";
        publish();
      }

      /** 「编辑」按钮：同一角色再点一次收起；换角色直接重开（草稿不跨角色保留）。 */
      function toggleBuiltinEdit(name) {
        var key = typeof name === "string" ? name : "";
        if (builtinEdit !== null && builtinEdit.name === key) {
          builtinEdit = null;
          setBuiltinNotice(key, "");
          publish();
          return;
        }
        beginBuiltinEdit(key);
      }

      function cancelBuiltinEdit() {
        builtinEdit = null;
        setBuiltinNotice("", "");
        publish();
      }

      /** 编辑面板里的单字段写入（只允许 roleOverrides 覆盖的四个字段）。 */
      function editBuiltinField(field, value) {
        if (builtinEdit === null) return;
        if (field !== "description" && field !== "prompt" && field !== "tier" && field !== "tools") return;
        var next = {
          name: builtinEdit.name,
          description: builtinEdit.description,
          prompt: builtinEdit.prompt,
          tier: builtinEdit.tier,
          tools: builtinEdit.tools,
          revision: builtinEdit.revision
        };
        if (field === "tools") next.tools = normalizeToolIds(value);
        else next[field] = typeof value === "string" ? value : builtinEdit[field];
        builtinEdit = next;
        setBuiltinNotice(next.name, "");
        publish();
      }

      /** 档位快捷组合：档位与工具集一起切到该档位（与角色库的「点一下批量勾选」同义）。 */
      function applyBuiltinTier(tier) {
        if (builtinEdit === null) return;
        var key = typeof tier === "string" && OVERRIDE_TIERS.indexOf(tier) >= 0 ? tier : builtinEdit.tier;
        builtinEdit = {
          name: builtinEdit.name,
          description: builtinEdit.description,
          prompt: builtinEdit.prompt,
          tier: key,
          tools: toolIdsOfTier(key),
          revision: builtinEdit.revision
        };
        setBuiltinNotice(builtinEdit.name, "");
        publish();
      }

      /** 整表写回 Config.roleOverrides（与 customRoles 同一 mutate 契约 + 同一 revision 冲突判定）。 */
      function writeOverrides(next, expected) {
        if (disposed || !scope || typeof scope.mutate !== "function") return Promise.resolve(false);
        saving = true;
        publish();
        var request;
        try {
          request = scope.mutate([{ op: "set", path: ["roleOverrides"], value: next }], expected);
        } catch (error) {
          saving = false;
          publish();
          return Promise.resolve(false);
        }
        return Promise.resolve(request).then(function (accepted) {
          if (disposed) return false;
          saving = false;
          if (accepted === true) lastValue = undefined;
          publish();
          return accepted === true;
        }, function () {
          if (disposed) return false;
          saving = false;
          publish();
          return false;
        });
      }

      /** 保存内置角色编辑：只写与内置默认不同的字段；全部回默认 → 删掉该条 override。 */
      function saveBuiltinEdit() {
        if (disposed || saving || builtinEdit === null) return Promise.resolve(false);
        var snapshot = readScope();
        if (snapshot.status !== "ready" || snapshot.writable !== true || conflicted) return Promise.resolve(false);
        if (builtinEdit.revision !== undefined && snapshot.revision !== builtinEdit.revision) {
          conflicted = true;
          publish();
          return Promise.resolve(false);
        }
        var draft = builtinEdit;
        if (OVERRIDE_TIERS.indexOf(draft.tier) < 0) {
          setBuiltinNotice(draft.name, "tierInvalid");
          publish();
          return Promise.resolve(false);
        }
        var name = draft.name;
        var next = applyOverrideDraft(currentOverrides(), draft);
        return writeOverrides(next, draft.revision).then(function (accepted) {
          if (disposed) return false;
          if (accepted === true) {
            builtinEdit = null;
            setBuiltinNotice(name, "saved");
          } else {
            setBuiltinNotice(name, "failed");
          }
          publish();
          return accepted === true;
        });
      }

      /** 「恢复默认」：删除该角色的 override（没覆盖过就只收起草稿）。 */
      function resetBuiltinOverride(name) {
        if (disposed || saving) return Promise.resolve(false);
        var key = typeof name === "string" ? name.trim() : "";
        if (key === "") return Promise.resolve(false);
        var snapshot = readScope();
        if (snapshot.status !== "ready" || snapshot.writable !== true || conflicted) return Promise.resolve(false);
        var list = currentOverrides();
        var next = [];
        var removed = false;
        for (var i = 0; i < list.length; i += 1) {
          if (list[i].name === key) {
            removed = true;
            continue;
          }
          next.push(list[i]);
        }
        if (builtinEdit !== null && builtinEdit.name === key) builtinEdit = null;
        if (!removed) {
          publish();
          return Promise.resolve(true);
        }
        return writeOverrides(next, snapshot.revision).then(function (accepted) {
          if (disposed) return false;
          setBuiltinNotice(key, accepted === true ? "saved" : "failed");
          publish();
          return accepted === true;
        });
      }

      /**
       * 改团队字段（name / description / slug）。
       * name 变更时：**新建行**（isNew）重算 id 并自动消歧；**已存团队保留原 id**，
       * 否则改名会把 Config.activeTeam 指向的 id 弄悬空。
       * slug 变更 = 用户亲手指定预设 id：打上 slugEdited，此后改名不再覆盖它。
       */
      function editTeam(index, field, value) {
        if (field !== "name" && field !== "description" && field !== "slug") return;
        if (!canEdit()) return;
        var current = beginTeamsDraft();
        if (index < 0 || index >= current.rows.length) return;
        if (current.rows[index][field] === value) return;
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          var copy = copyTeam(row);
          copy.isNew = row.isNew === true;
          if (i === index) {
            copy[field] = value;
            if (field === "slug") copy.slugEdited = true;
            if (field === "name" && copy.isNew === true) {
              copy.id = uniqueTeamId(value, takenIdsExcept(current.rows, index));
              // 没手改过的行让输入框跟着新 id 走；手改过就保持用户填的值不动。
              if (copy.slugEdited !== true) copy.slug = copy.id;
            }
          }
          next.push(copy);
        }
        pushTeamsRows(next);
      }

      /**
       * 勾选/取消一个成员（成员多选）。
       *
       * 判定全部交给纯函数 {@link toggleMemberState}：一个团队最多一个队长类型角色 ——
       * 勾选队长类型且队里已有队长类型 → **拒绝**（草稿不动，只记一条提示）；否则自动设为队长。
       * 取消的若是当前队长 → lead 清空（保存时由 validateTeams 报「必须有一位队长类型角色」）。
       */
      function toggleTeamMember(index, roleName) {
        if (typeof roleName !== "string" || roleName === "") return;
        if (!canEdit()) return;
        var rolesNow = currentRoles();
        var rowsNow = teamsDraft !== null ? teamsDraft.rows : currentTeams();
        if (index < 0 || index >= rowsNow.length) return;
        // 先在草稿之外做一次纯判定：被拒时**根本不建草稿**，避免把「点了一下」记成未保存改动。
        var probe = toggleMemberState(copyTeam(rowsNow[index]), roleName, rolesNow);
        if (probe.rejected !== "") {
          teamMemberNotice = { index: index, code: "leadExists", name: probe.currentLead };
          teamsNotice = "";
          publish();
          return;
        }
        var current = beginTeamsDraft();
        if (index < 0 || index >= current.rows.length) return;
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          var copy = copyTeam(row);
          copy.isNew = row.isNew === true;
          if (i === index) {
            var result = toggleMemberState(copy, roleName, rolesNow);
            copy.members = result.members;
            copy.lead = result.lead;
          }
          next.push(copy);
        }
        pushTeamsRows(next);
      }

      /**
       * 指定队长：只接受当前已勾选的成员，其它值一律落成 ""（再由默认规则补）。
       * 取消勾选原队长后 lead 会悬空 —— 故意不自动改，交给 validateTeams 标红拦截。
       */
      function setTeamLead(index, roleName) {
        if (typeof roleName !== "string") return;
        if (!canEdit()) return;
        var current = beginTeamsDraft();
        if (index < 0 || index >= current.rows.length) return;
        if (current.rows[index].lead === roleName) return;
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          var row = current.rows[i];
          var copy = copyTeam(row);
          copy.isNew = row.isNew === true;
          if (i === index) copy.lead = copy.members.indexOf(roleName) >= 0 ? roleName : "";
          next.push(copy);
        }
        pushTeamsRows(next);
      }

      /** 追加一个空团队（id 先按 "team"/"team-2"… 占位，填名后自动重算）。 */
      function addTeam() {
        if (!canEdit()) return;
        var current = beginTeamsDraft();
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          var copy = copyTeam(current.rows[i]);
          copy.isNew = current.rows[i].isNew === true;
          next.push(copy);
        }
        next.push(emptyTeam(uniqueTeamId("", takenIdsExcept(next, -1))));
        expandedTeam = next.length - 1;
        pushTeamsRows(next);
      }

      /**
       * 「复制为我的团队」：拿内置团队当模板，追加一条**普通用户团队**草稿行。
       *   · 名称加「-副本」后缀；id 走 uniqueTeamId 消歧（基准 `<内置 id>-copy`，
       *     并把内置 id 一并算作已占用——预设 id 不能和内置团队撞车）；
       *   · 复制完直接展开该行（可改成员 / 队长 / 预设 id），之后可保存、可删除。
       * @param builtinId - ROLE_CATALOG.builtinTeams[].id
       */
      function copyBuiltinTeam(builtinId) {
        if (!canEdit()) return;
        var specs = builtinTeamsOf(ROLE_CATALOG);
        var template = null;
        for (var s = 0; s < specs.length; s += 1) {
          if (specs[s].id === builtinId) template = specs[s];
        }
        if (template === null) return;
        var current = beginTeamsDraft();
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          var copy = copyTeam(current.rows[i]);
          copy.isNew = current.rows[i].isNew === true;
          next.push(copy);
        }
        var taken = takenIdsExcept(next, -1);
        for (var t2 = 0; t2 < specs.length; t2 += 1) {
          if (taken.indexOf(specs[t2].id) < 0) taken.push(specs[t2].id);
        }
        var name = template.name + "-副本";
        // 复制的团队是**用户团队**，队长必须 ∈ members（validateTeams 会拦悬空 lead）。
        // 内置团队的 lead 是主代理 co-orchestrator（不在成员里），直接抄过来会让副本一建就标红
        // 且无法保存：优先挑第一个「队长」类型的成员，挑不到就交给默认规则（再让用户在下拉里改）。
        var leadForCopy = template.members.indexOf(template.lead) >= 0
          ? template.lead
          : effectiveTeamLead({ members: template.members, lead: "" });
        var row = copyTeam({
          id: uniqueTeamId(template.id + "-copy", taken),
          name: name,
          description: template.description,
          members: template.members.slice(),
          lead: leadForCopy
        });
        row.isNew = true;
        row.slugEdited = false;
        row.slug = row.id;
        next.push(row);
        expandedTeam = next.length - 1;
        pushTeamsRows(next);
      }

      /** 单 path 写配置：异常与 rejected promise 都归一为 false（不抛给 UI）。 */
      function mutatePath(path, value, expected) {
        if (disposed || !scope || typeof scope.mutate !== "function") return Promise.resolve(false);
        var request;
        try {
          request = scope.mutate([{ op: "set", path: path, value: value }], expected);
        } catch (error) {
          return Promise.resolve(false);
        }
        return Promise.resolve(request).then(function (accepted) {
          return accepted === true;
        }, function () {
          return false;
        });
      }

      /**
       * 删除一个团队行。
       * 只写 Config.teams：`activeTeam` 已废弃，本页不再写入（会话限制改由 Agent 预设承担）。
       */
      function removeTeam(index) {
        if (!canEdit()) return Promise.resolve(false);
        var current = beginTeamsDraft();
        if (index < 0 || index >= current.rows.length) return Promise.resolve(false);
        var next = [];
        for (var i = 0; i < current.rows.length; i += 1) {
          if (i === index) continue;
          var copy = copyTeam(current.rows[i]);
          copy.isNew = current.rows[i].isNew === true;
          next.push(copy);
        }
        expandedTeam = -1;
        pushTeamsRows(next);
        return Promise.resolve(true);
      }

      function discardTeams() {
        if (saving) return;
        teamsDraft = null;
        teamsSaved = false;
        teamsFailed = false;
        teamErrors = [];
        teamsNotice = "";
        teamMemberNotice = null;
        expandedTeam = -1;
        publish();
      }

      /** 整表写回 Config.teams（数组字段整体替换，与 skills / customRoles 同一 mutate 契约）。 */
      function saveTeams() {
        if (disposed || saving || teamsDraft === null) return Promise.resolve(false);
        var snapshot = readScope();
        if (snapshot.status !== "ready" || snapshot.writable !== true || conflicted) return Promise.resolve(false);
        if (teamsDraft.revision !== undefined && snapshot.revision !== teamsDraft.revision) {
          conflicted = true;
          publish();
          return Promise.resolve(false);
        }
        // 自定义角色类型（kind）可能刚在「角色库」里改过还没保存，校验/落库都带上当前编辑行，
        // 否则会把用户刚设成「队长」类型的自定义角色误判成队员。
        var rolesNow = currentRoles();
        var errors = validateTeams(teamsDraft.rows, rolesNow);
        if (countTeamErrors(errors) > 0) {
          teamErrors = errors;
          teamsSaved = false;
          teamsFailed = false;
          publish();
          return Promise.resolve(false);
        }
        var expected = teamsDraft.revision;
        var next = teamsToConfig(teamsDraft.rows, rolesNow);
        saving = true;
        teamsSaved = false;
        teamsFailed = false;
        teamErrors = [];
        publish();
        var request;
        try {
          request = scope.mutate([{ op: "set", path: ["teams"], value: next }], expected);
        } catch (error) {
          saving = false;
          teamsFailed = true;
          publish();
          return Promise.resolve(false);
        }
        return Promise.resolve(request).then(function (accepted) {
          if (disposed) return false;
          saving = false;
          if (accepted === true) {
            teamsDraft = null;
            teamsFailed = false;
            teamsSaved = true;
            teamsNotice = "";
            teamMemberNotice = null;
            lastValue = undefined;
          } else {
            teamsFailed = true;
          }
          publish();
          return accepted === true;
        }, function () {
          if (disposed) return false;
          saving = false;
          teamsFailed = true;
          publish();
          return false;
        });
      }

      function loadCatalog() {
        catalogGeneration += 1;
        var generation = catalogGeneration;
        catalogStatus = "loading";
        catalogError = "";
        publish();

        var remote = ctx && ctx.remote;
        var request;
        try {
          if (!remote || !remote.session || typeof remote.session.modelCatalog !== "function") {
            throw new Error("remote.session.modelCatalog is unavailable");
          }
          request = remote.session.modelCatalog();
        } catch (error) {
          catalogStatus = "error";
          catalogError = messageOf(error);
          publish();
          return;
        }

        Promise.resolve(request).then(function (response) {
          if (disposed || generation !== catalogGeneration) return;
          if (!response || response.ok !== true) {
            catalogStatus = "error";
            catalogError = response && response.error ? messageOf(response.error) : "modelCatalog failed";
            publish();
            return;
          }
          var groups = response.value && Array.isArray(response.value.groups) ? response.value.groups : [];
          var providers = [];
          var byProvider = {};
          var effortsByModel = {};
          for (var i = 0; i < groups.length; i += 1) {
            var group = groups[i];
            if (!group || typeof group.id !== "string" || group.id === "") continue;
            var models = [];
            var effortsForProvider = {};
            var list = Array.isArray(group.models) ? group.models : [];
            for (var j = 0; j < list.length; j += 1) {
              var model = list[j];
              if (!model || typeof model.id !== "string" || model.id === "") continue;
              models.push({ id: model.id, label: modelLabel(model) });
              // 不支持推理强度的模型整个 reasoning 字段缺失 → reasoningEffortsOf 返回空数组，
              // 这里只在非空时登记，渲染层用「查不到 = 不支持」判定。
              var efforts = reasoningEffortsOf(model);
              if (efforts.length > 0) effortsForProvider[model.id] = efforts;
            }
            byProvider[group.id] = models;
            if (Object.keys(effortsForProvider).length > 0) effortsByModel[group.id] = effortsForProvider;
            providers.push({ id: group.id, label: providerLabel(group) });
          }
          providers.sort(function (left, right) {
            if (left.id === right.id) return 0;
            return left.id < right.id ? -1 : 1;
          });
          catalogProviders = providers;
          catalogByProvider = byProvider;
          catalogEfforts = effortsByModel;
          catalogStatus = "ready";
          catalogError = "";
          publish();
        }, function (error) {
          if (disposed || generation !== catalogGeneration) return;
          catalogStatus = "error";
          catalogError = messageOf(error);
          publish();
        });
      }

      function start() {
        var disposers = [];
        if (scope && typeof scope.subscribe === "function") {
          var offScope = scope.subscribe(onScopeChange);
          if (typeof offScope === "function") disposers.push(offScope);
        }
        var remote = ctx && ctx.remote;
        if (remote && typeof remote.$on === "function") {
          try {
            var offCatalog = remote.$on("llm/adapters-updated", function () {
              loadCatalog();
            });
            if (typeof offCatalog === "function") disposers.push(offCatalog);
          } catch (error) {
            /* 事件订阅失败只影响目录自动刷新，不阻断页面 */
          }
        }
        publish();
        loadCatalog();
        loadPresets();
        return function () {
          disposed = true;
          var snapshot = disposers;
          disposers = [];
          for (var i = 0; i < snapshot.length; i += 1) {
            try {
              snapshot[i]();
            } catch (error) {
              /* dispose 失败不影响其余清理 */
            }
          }
        };
      }

      publish();

      return {
        store: store,
        start: start,
        editRow: editRow,
        resetRow: resetRow,
        discard: discard,
        save: save,
        loadCatalog: loadCatalog,
        loadPresets: loadPresets,
        editRole: editRole,
        addRole: addRole,
        removeRole: removeRole,
        duplicateRole: duplicateRole,
        focusRoleEditor: focusRoleEditor,
        discardRoles: discardRoles,
        saveRoles: saveRoles,
        chooseTemplate: chooseTemplate,
        applyTierTools: applyTierTools,
        toggleRolePicker: toggleRolePicker,
        newRoleFromTemplate: newRoleFromTemplate,
        setRoleSearch: setRoleSearch,
        editSkillRow: editSkillRow,
        resetSkillRow: resetSkillRow,
        toggleTeam: toggleTeam,
        toggleTeamPreview: toggleTeamPreview,
        toggleRoleDetail: toggleRoleDetail,
        toggleBuiltinEdit: toggleBuiltinEdit,
        editBuiltinField: editBuiltinField,
        applyBuiltinTier: applyBuiltinTier,
        saveBuiltinEdit: saveBuiltinEdit,
        resetBuiltinOverride: resetBuiltinOverride,
        cancelBuiltinEdit: cancelBuiltinEdit,
        editTeam: editTeam,
        toggleTeamMember: toggleTeamMember,
        setTeamLead: setTeamLead,
        addTeam: addTeam,
        copyBuiltinTeam: copyBuiltinTeam,
        removeTeam: removeTeam,
        discardTeams: discardTeams,
        saveTeams: saveTeams,
        setTab: setTab
      };
    }

    /**
     * 设置页 tab 归一：只接受 "teams" / "roles" 两个值，其余（含 undefined / null / 脏值）
     * 一律回落到默认选中项 "teams"。纯函数，便于状态推演与测试。
     */
    function normalizeTab(value) {
      return value === "roles" ? "roles" : "teams";
    }

